import { visuallyHiddenStyle } from "../../a11y/visually-hidden";
import { getGridKeyAction, getGridNextIndex } from "../../collection/grid-collection";
import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import { resolveDir } from "../../dom/text-dir";
import { getRovingTabIndex } from "../../focus/roving-focus";
import type { InputProps, NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import type { Align, Side } from "../../positioner/compute-position";
import {
  type ColorChannel,
  type ColorFormat,
  type ColorNumericChannel,
  type ColorValue,
  getChannelRange,
  getChannelValue,
  toHex,
} from "../../utils/color";
import { roundToPrecision, toPercent } from "../../utils/range";
import { parts } from "./color-picker.anatomy";
import {
  getAreaId,
  getAreaXInputId,
  getAreaYInputId,
  getBackdropId,
  getCancelTriggerId,
  getChannelInputId,
  getChannelLabelId,
  getChannelThumbId,
  getCloseTriggerId,
  getContentId,
  getEyedropperTriggerId,
  getFormatSelectId,
  getHiddenInputId,
  getLabelId,
  getPositionerId,
  getRootId,
  getSurfaceEl,
  getSwatchGroupId,
  getSwatchId,
  getTitleId,
  getTriggerId,
  getValueTextId,
} from "./color-picker.dom";
import { getAreaKeyEvent, getChannelKeyEvent } from "./color-picker.props";
import type {
  ColorPickerApi,
  ColorPickerChannelProps,
  ColorPickerInputProps,
  ColorPickerSchema,
  ColorPickerSwatchProps,
  ColorPickerSwatchRowProps,
} from "./color-picker.types";

/**
 * The core places percentages, the sheet does the layout. Rounded, so a third of
 * a track does not serialise seventeen digits into the markup — and so the server
 * and the client write the same string.
 */
function pct(ratio: number): string {
  return `${roundToPrecision(ratio * 100, 4)}%`;
}

/**
 * The name a channel answers to when the consumer renders no `channelLabel` and
 * passes no `translations.channelLabel`.
 *
 * English on purpose — the panel's icon-only controls have no `:empty` glyph, so
 * withholding a name would ship a nameless button — but reachable, which is the
 * part that was missing. The comment here used to justify the strings by
 * `dialog:close-trigger`'s "Close"; that precedent does not exist
 * (`dialog.connect.ts` emits id, type, state and click, and no name at all), and
 * the honest precedent is `toast` and `pagination`, which ship an English default
 * behind a `translations` seam.
 */
const CHANNEL_NAMES: Readonly<Record<ColorChannel, string>> = {
  hue: "Hue",
  saturation: "Saturation",
  brightness: "Brightness",
  alpha: "Opacity",
  red: "Red",
  green: "Green",
  blue: "Blue",
  hex: "Hex",
};

/** Alpha is shown and typed in per cent. */
function displayValue(color: ColorValue, channel: ColorNumericChannel): number {
  const raw = getChannelValue(color, channel);
  return Math.round(channel === "alpha" ? raw * 100 : raw);
}

export function connect<T extends PropTypes>(
  service: Service<ColorPickerSchema>,
  normalize: NormalizeProps<T>,
): ColorPickerApi<T> {
  const { context, computed, prop, send, scope } = service;

  const color = context.get("color");
  const open = context.get("open");
  const format = context.get("format");
  const presentation = computed("presentation");
  const interactive = computed("isInteractive");
  const valueString = computed("valueString");
  const colorName = computed("colorName");
  const translations = prop("translations");
  const channels = computed("channels");
  const swatchList = computed("swatchList");
  const swatchColumns = computed("swatchColumns");
  const rgb = computed("rgb");

  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const invalid = prop("invalid");
  const required = prop("required");
  const dir = prop("dir");
  const alphaEnabled = prop("alpha");

  const state = open ? "open" : "closed";
  const placement = context.get("currentPlacement");
  const [side, align = "center"] = placement.split("-") as [Side, Align | undefined];

  const engagedTarget = context.get("engagedTarget");
  const engaged = engagedTarget !== null;
  const activeChannel = context.get("activeChannel");
  const areaDragging = context.get("areaDragging");
  const dragging = areaDragging || (activeChannel !== null && !engaged);
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const drafts = context.get("inputDrafts");
  const invalidDrafts = context.get("invalidDrafts");
  const highlighted = context.get("highlightedSwatch");
  const selectedSwatch = swatchList.indexOf(valueString);
  // Exactly one cell is in the tab order: the highlighted one, else the selected
  // one, else the first — `getRovingTabIndex` compares against this and nothing else.
  const rovingSwatch = highlighted >= 0 ? highlighted : selectedSwatch >= 0 ? selectedSwatch : 0;

  const triggerId = getTriggerId(scope);
  const contentId = getContentId(scope);
  const hasLabel = context.get("hasLabel");
  const hasTitle = context.get("hasTitle");
  const hasValueText = context.get("hasValueText");
  const labelledChannels = context.get("labelledChannels");
  const label = prop("label");
  const labelledBy = prop("labelledBy");

  const opaque = `rgb(${Math.round(rgb.r)} ${Math.round(rgb.g)} ${Math.round(rgb.b)})`;
  const painted = `rgb(${Math.round(rgb.r)} ${Math.round(rgb.g)} ${Math.round(rgb.b)} / ${roundToPrecision(color.a, 4)})`;

  /**
   * The colour, published for the sheet on every part that paints with it. The
   * hue goes out twice — as a number for arithmetic and as a colour — because
   * composing `hsl()` from an unregistered custom property is fragile and
   * `@property` is not part of the contract.
   */
  const colorVars: Readonly<Record<string, string>> = {
    "--sui-color-picker-value": painted,
    "--sui-color-picker-opaque": opaque,
    "--sui-color-picker-hue": String(roundToPrecision(color.h, 2)),
    "--sui-color-picker-hue-color": `hsl(${roundToPrecision(color.h, 2)} 100% 50%)`,
    "--sui-color-picker-alpha": String(roundToPrecision(color.a, 4)),
  };

  const stateAttrs = {
    "data-disabled": dataAttr(disabled),
    "data-readonly": dataAttr(readOnly),
    "data-invalid": dataAttr(invalid),
  };

  const channelPercent = (channel: ColorNumericChannel): number => {
    const range = getChannelRange(channel);
    return toPercent(getChannelValue(color, channel), range.min, range.max);
  };

  const channelName = (channel: ColorChannel): string =>
    translations?.channelLabel?.(channel) ?? CHANNEL_NAMES[channel];

  interface ChannelNaming {
    readonly "aria-labelledby"?: string | undefined;
    readonly "aria-label"?: string | undefined;
  }

  /**
   * One text names the thumb *and* the field beside it —
   * but only when that text is on screen. A `channelLabel` nobody rendered would
   * make `aria-labelledby` a dangling IDREF *and* leave the control nameless, so
   * the library's own name stands in.
   *
   * Asked per channel, because a panel that labels its sliders and not its hex
   * field is an ordinary composition: a single flag for the whole surface answered
   * "labelled" for the field too (audit of 2026-09-05).
   */
  const channelNaming = (channel: ColorChannel): ChannelNaming =>
    labelledChannels.includes(channel)
      ? { "aria-labelledby": getChannelLabelId(scope, channel) }
      : { "aria-label": channelName(channel) };

  const channelValueText = (channel: ColorNumericChannel): string | undefined => {
    if (channel === "hue") return `${Math.round(color.h)}°, ${colorName}`;
    if (channel === "alpha") return `${Math.round(color.a * 100)}%`;
    if (channel === "saturation" || channel === "brightness") {
      return `${Math.round(getChannelValue(color, channel))}%`;
    }
    // Red, green and blue: the number *is* the whole story, and a `valuetext`
    // repeating `valuenow` makes some readers say it twice (the slider's rule).
    return undefined;
  };

  const areaValueText = (lead: "saturation" | "brightness"): string => {
    const s = Math.round(color.s);
    const v = Math.round(color.v);
    const override = translations?.areaValueText;
    if (override !== undefined) {
      return override({ lead, saturation: s, brightness: v, colorName });
    }
    return lead === "saturation"
      ? `Saturation ${s}%, brightness ${v}%, ${colorName}`
      : `Brightness ${v}%, saturation ${s}%, ${colorName}`;
  };

  function onAreaKeyDown(event: KeyboardEvent): void {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
    // The direction is resolved here rather than at the top of `connect`: with no
    // `dir` prop the answer is read off the surface, and a DOM read during render
    // would run on the server.
    const next = getAreaKeyEvent(event.key, {
      dir: resolveDir(dir, getSurfaceEl(scope)),
      shiftKey: event.shiftKey,
    });
    if (next === null) return;
    // **Always, and before the guard's answer can matter.** These are real
    // `<input type="range">` elements: their own step logic would run *in
    // addition* to ours on every one of these keys, including Home, End and the
    // page keys, and the value would move twice.
    event.preventDefault();
    if (!interactive) return;
    send(next);
  }

  function areaInputProps(axis: "x" | "y"): InputProps {
    const horizontal = axis === "x";
    const channel = horizontal ? "saturation" : "brightness";
    return {
      type: "range",
      min: 0,
      max: 100,
      step: prop("step"),
      // Written from the context on every render and never read back as input:
      // the colour is the source of truth, and the native value is a mirror.
      value: Math.round(getChannelValue(color, channel)),
      disabled,
      // `aria-readonly`, not the HTML `readonly`: that one is inert on a range input.
      "aria-readonly": ariaAttr(readOnly),
      style: visuallyHiddenStyle,
      "aria-label": channelName(channel),
      "aria-valuetext": areaValueText(channel),
      // One tab stop for the area. The second axis exists so its value is
      // published and so a pad can aim at it, never so a Tab can land on it.
      tabIndex: horizontal ? undefined : -1,
      "data-axis": axis,
      onKeyDown: onAreaKeyDown,
      onChange(event: Event) {
        const input = event.currentTarget as HTMLInputElement | null;
        if (input === null) return;
        send({ type: "AREA.SET", axis, value: Number(input.value) });
      },
      onFocusIn() {
        send({ type: "FOCUS.IN" });
      },
      onFocusOut() {
        send({ type: "FOCUS.OUT" });
      },
    };
  }

  return {
    open,
    value: valueString,
    color,
    rgb,
    format,
    formats: prop("formats"),
    channels,
    swatches: swatchList,
    swatchColumns,
    swatchRows: computed("swatchRows"),
    highlightedSwatch: highlighted,
    presentation,
    placement,
    dragging,
    engaged,
    engagedTarget,
    disabled,
    eyedropperSupported: context.get("eyedropperSupported"),
    focusSource,
    focusVisible,
    triggerId,
    contentId,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },

    setValue(next: string): void {
      send({ type: "VALUE.SET", value: next });
    },

    setColor(next: ColorValue): void {
      send({ type: "VALUE.SET", value: toHex(next, next.a < 1) });
    },

    setFormat(next: ColorFormat): void {
      send({ type: "FORMAT.SET", format: next });
    },

    setChannelValue(channel: ColorNumericChannel, next: number): void {
      send({ type: "CHANNEL.SET", channel, value: next });
    },

    getChannelValue: (channel: ColorNumericChannel): number => getChannelValue(color, channel),
    getChannelPercent: channelPercent,
    getChannelName: channelName,

    addSwatch(): void {
      send({ type: "SWATCH.ADD" });
    },

    selectSwatch(index: number): void {
      send({ type: "SWATCH.SELECT", index });
    },

    openEyedropper(): void {
      send({ type: "EYEDROPPER.OPEN" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        dir,
        "data-presentation": presentation,
        "data-state": state,
        "data-variant": prop("variant"),
        "data-format": format,
        // Not `aria-required`, and not on the trigger where it used to sit: the
        // trigger declares no `role`, so it is an implicit `button`, and the only
        // role-specific ARIA it admits is `aria-expanded` and `aria-pressed`. The
        // global attributes ride on every role — which is why `aria-invalid` below
        // is legal — and `aria-required` is not one of them, so axe counted it
        // under `aria-allowed-attr`. `checkbox-group.connect.ts:55-60` already
        // settled this shape: the state is published as data, and requiredness
        // belongs to the consumer's validation. On the root because
        // `presentation="inline"` renders no trigger at all
        // (`color-picker.anatomy.ts:6`), and the root is the one part that exists
        // in every presentation and already carries the `data-*` state family.
        "data-required": dataAttr(required),
        // On the root *and* on the element being held — the `data-engaged`
        // contract (architecture.md), whose first emitter was the slider.
        "data-engaged": dataAttr(engaged),
        "data-dragging": dataAttr(dragging),
        "data-empty": dataAttr(color.a === 0),
        style: colorVars,
      }),

    // A `span`, not a `<label>`: `for` only names *labelable* elements, and
    // neither a `<button>`-less inline panel nor a `div[role="slider"]` is one in
    // every presentation. The trigger points back with `aria-labelledby`.
    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, ...stateAttrs, id: getLabelId(scope) }),

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        ...stateAttrs,
        id: triggerId,
        type: "button",
        disabled,
        "aria-haspopup": "dialog",
        "aria-expanded": boolAttr(open),
        // Only while the surface exists: `content` is unmounted when closed, and
        // an IDREF pointing at nothing is a dangling reference *and* an axe
        // failure (`aria-valid-attr-value`).
        "aria-controls": open ? contentId : undefined,
        // The label *and* the colour, in that order. `aria-labelledby` replaces the
        // element's text outright, so pointing it at the label alone drops the colour
        // from the name entirely: a picker that renders the `label` part announces
        // "Tint" and never which colour it holds, while one without a label announces
        // the colour through `aria-label` below.
        //
        // Naming the element's own id is how ARIA says "and my own contents", and it
        // is the one IDREF that can never dangle — but it only says anything when the
        // button *has* contents. It does not: the composed layer renders `valueText`
        // beside the trigger, not inside it (the default `well` variant is a 48x24
        // swatch with no room for a string), and the swatch within is `aria-hidden`.
        // Measured on the shipped demo, both triggers came out named "Accent" and
        // "Brand", never the colour — the very regression this comment used to say
        // was fixed.
        //
        // So point at `valueText` when it is on the page, and keep the self-reference
        // as the fallback when it is not. `hasValueText` is read from the live DOM by
        // `syncParts`, like `hasLabel` beside it, which is what keeps the IDREF from
        // dangling on a picker that leaves the part out.
        "aria-labelledby": hasLabel
          ? `${getLabelId(scope)} ${hasValueText ? getValueTextId(scope) : triggerId}`
          : labelledBy,
        "aria-describedby": prop("describedBy"),
        // `aria-invalid` alone. `aria-required` sat here too until it was measured:
        // this button declares no `role`, so its role is the implicit `button`,
        // which admits `aria-expanded` and `aria-pressed` on top of the global
        // attributes. `aria-invalid` survives because it is global; `aria-required`
        // is not, so the role threw it away and axe counted it under
        // `aria-allowed-attr`. The comment it replaces claimed `select` as the
        // precedent for the pair; `select` is only legal because
        // `select.connect.ts:272` declares `role: "combobox"`, which this trigger
        // cannot take (a combobox requires `aria-controls`, and the content is
        // unmounted while closed — see the note above). Requiredness is published
        // as `data-required` on the root, the way `checkbox-group.connect.ts:55-60`
        // settled it.
        "aria-invalid": ariaAttr(invalid),
        // Named by the value when nothing else names it: the swatch inside is
        // decoration, so without this the button would reach axe with no name.
        "aria-label": hasLabel || labelledBy !== undefined ? undefined : (label ?? valueString),
        "data-presentation": presentation,
        "data-state": state,
        "data-variant": prop("variant"),
        "data-focus-visible": dataAttr(focusVisible),
        "data-focus-source": focusSource ?? undefined,
        style: colorVars,
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || disabled || event.repeat) return;
          if (event.ctrlKey || event.metaKey || event.altKey) return;
          // Space opens on keyup — the APG split, and what stops the press from
          // leaking into the surface it opens.
          if (event.key === " ") {
            event.preventDefault();
            return;
          }
          if (event.key !== "ArrowDown") return;
          event.preventDefault();
          send({ type: "TRIGGER.CLICK" });
        },
        onKeyUp(event) {
          if (event.defaultPrevented || disabled || event.key !== " ") return;
          if (event.ctrlKey || event.metaKey || event.altKey) return;
          event.preventDefault();
          send({ type: "TRIGGER.CLICK" });
        },
        onFocusIn() {
          send({ type: "FOCUS.IN" });
        },
        onFocusOut() {
          send({ type: "FOCUS.OUT" });
        },
      }),

    getTriggerSwatchProps: (): T["element"] =>
      normalize.element({
        ...parts.triggerSwatch.attrs,
        ...stateAttrs,
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        style: colorVars,
      }),

    /**
     * Real text, and deliberately not `aria-hidden`: on a `<button>` the contents
     * *are* the name, so hiding the only string in there is how a control ends up
     * nameless. The trigger's `aria-label` says the same words, so nothing is read
     * twice.
     */
    getValueTextProps: (): T["element"] =>
      normalize.element({
        ...parts.valueText.attrs,
        ...stateAttrs,
        id: getValueTextId(scope),
        "data-format": format,
      }),

    /**
     * `type="hidden"`, never `type="color"`. A real colour input would open the
     * platform's own picker on click and put a second value-bearing control in the
     * accessibility tree — two elements each claiming to hold the colour.
     */
    getHiddenInputProps: (): T["input"] =>
      normalize.input({
        ...parts.hiddenInput.attrs,
        id: getHiddenInputId(scope),
        type: "hidden",
        name: prop("name"),
        form: prop("form"),
        // Native rule: a disabled control is not submitted.
        disabled,
        value: valueString,
      }),

    // The sheet's alone: an anchored popup that dimmed the page would swallow the
    // very click meant to dismiss it.
    getBackdropProps: (): T["element"] =>
      normalize.element({
        ...parts.backdrop.attrs,
        id: getBackdropId(scope),
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        "data-presentation": presentation,
      }),

    /**
     * The floating element. `data-side`/`data-align` are deliberately absent here
     * — the position effect writes onto this node directly, and an adapter that
     * also rendered them would fight it over every commit.
     */
    getPositionerProps: (): T["element"] =>
      normalize.element({
        ...parts.positioner.attrs,
        id: getPositionerId(scope),
        "data-sui-layer-parent": prop("parentId"),
        "data-state": state,
        "data-presentation": presentation,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        ...stateAttrs,
        id: contentId,
        // Inline, the panel is always open, never modal and has no way out: it is
        // embedded content, and a `dialog` would promise a closing it cannot keep.
        role: presentation === "inline" ? "group" : "dialog",
        "aria-modal": computed("isModal") ? "true" : undefined,
        dir: context.get("surfaceDir") ?? dir,
        tabIndex: -1,
        // The naming a `field` hands down reaches here too, and it has to: in
        // `presentation="inline"` there is no trigger, so a hub that stopped at the
        // trigger left the panel — the only thing on screen — tied to nothing at
        // all. Order of preference: a rendered `title`, then whatever named the
        // control from outside, then the library's own default.
        "aria-labelledby": hasTitle ? getTitleId(scope) : labelledBy,
        "aria-label": hasTitle || labelledBy !== undefined ? undefined : (label ?? "Color picker"),
        "aria-describedby": prop("describedBy"),
        "data-presentation": presentation,
        "data-state": state,
        "data-format": format,
        "data-side": side,
        "data-align": align,
        "data-placement": placement,
        "data-engaged": dataAttr(engaged),
        // The surface applies the glass material, so it owes its contents
        // the on-glass palette (architecture.md).
        "data-sui-on-glass": "",
        "data-snav": "container",
        "data-snav-trap": computed("isModal") ? "" : undefined,
        style: colorVars,
      }),

    getArrowProps: (): T["element"] =>
      normalize.element({
        ...parts.arrow.attrs,
        "aria-hidden": ariaAttr(true),
        "data-side": side,
      }),

    getTitleProps: (): T["element"] =>
      normalize.element({ ...parts.title.attrs, id: getTitleId(scope) }),

    /**
     * Sheet only, and a sibling of the dialog. `tabindex="-1"`: a pointer and touch
     * affordance whose keyboard and screen-reader path is Escape or B — the
     * `select:cancelTrigger` precedent, and it is what keeps `End` from landing on
     * a row the native control does not draw.
     */
    getCancelTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.cancelTrigger.attrs,
        id: getCancelTriggerId(scope),
        type: "button",
        tabIndex: -1,
        "data-state": state,
        "data-presentation": presentation,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CANCEL.CLICK" });
        },
      }),

    // Never disabled with the rest of the picker: a surface opened and then
    // disabled keeps it as its one tab stop, and a sheet's cancel card is already
    // out of the tab order (decision 61).
    getCloseTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.closeTrigger.attrs,
        id: getCloseTriggerId(scope),
        type: "button",
        "aria-label": translations?.closeLabel ?? "Close",
        "data-state": state,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLOSE.CLICK" });
        },
      }),

    /**
     * `role="group"`, never `role="application"`. WAI-ARIA 1.3 has no
     * two-dimensional slider and the APG has no colour-picker pattern; the two
     * hidden `<input type="range">` in the thumb are what publish a value, a name
     * and a `valuetext` a reader can use, where `application` would only silence
     * the browse mode and announce nothing.
     */
    getAreaProps: (): T["element"] =>
      normalize.element({
        ...parts.area.attrs,
        ...stateAttrs,
        id: getAreaId(scope),
        role: "group",
        "aria-label": translations?.areaLabel ?? "Saturation and brightness",
        "data-dragging": dataAttr(areaDragging),
        "data-engaged": dataAttr(engagedTarget === "area"),
        // The modality alone, paired with `:focus-within` in the sheet: the ring
        // belongs to whichever element actually has the focus, and the core has no
        // business asking the document which one that is during a render.
        "data-focus-source": focusSource ?? undefined,
        // The finger owns both axes for the length of the gesture; a scroll
        // container underneath must not take either away mid-drag.
        style: { ...colorVars, touchAction: "none" },
      }),

    getAreaBackgroundProps: (): T["element"] =>
      normalize.element({
        ...parts.areaBackground.attrs,
        "aria-hidden": ariaAttr(true),
        style: colorVars,
      }),

    getAreaThumbProps: (): T["element"] =>
      normalize.element({
        ...parts.areaThumb.attrs,
        role: "presentation",
        "data-dragging": dataAttr(areaDragging),
        "data-engaged": dataAttr(engagedTarget === "area"),
        style: {
          ...colorVars,
          "--sui-color-picker-area-x": pct(color.s / 100),
          "--sui-color-picker-area-y": pct(color.v / 100),
        },
      }),

    getAreaXInputProps: (): T["input"] =>
      normalize.input({
        ...parts.areaXInput.attrs,
        id: getAreaXInputId(scope),
        ...areaInputProps("x"),
      }),

    getAreaYInputProps: (): T["input"] =>
      normalize.input({
        ...parts.areaYInput.attrs,
        id: getAreaYInputId(scope),
        ...areaInputProps("y"),
      }),

    getChannelSliderProps: ({ channel }: ColorPickerChannelProps): T["element"] =>
      normalize.element({
        ...parts.channelSlider.attrs,
        ...stateAttrs,
        "data-channel": channel,
        // Horizontal in v1: no design draws a vertical colour track, and an
        // orientation nobody renders is a second geometry to keep correct.
        "data-orientation": "horizontal",
        "data-dragging": dataAttr(activeChannel === channel && !engaged),
        "data-engaged": dataAttr(engagedTarget === channel),
        style: {
          ...colorVars,
          "--sui-color-picker-channel-percent": pct(channelPercent(channel)),
          touchAction: "none",
        },
      }),

    getChannelLabelProps: ({ channel }: ColorPickerInputProps): T["element"] =>
      normalize.element({
        ...parts.channelLabel.attrs,
        id: getChannelLabelId(scope, channel),
        "data-channel": channel,
      }),

    getChannelSliderTrackProps: ({ channel }: ColorPickerChannelProps): T["element"] =>
      normalize.element({
        ...parts.channelSliderTrack.attrs,
        "aria-hidden": ariaAttr(true),
        "data-channel": channel,
        style: {
          ...colorVars,
          "--sui-color-picker-channel-percent": pct(channelPercent(channel)),
        },
      }),

    getChannelSliderRangeProps: ({ channel }: ColorPickerChannelProps): T["element"] =>
      normalize.element({
        ...parts.channelSliderRange.attrs,
        "aria-hidden": ariaAttr(true),
        "data-channel": channel,
        style: { "--sui-color-picker-channel-percent": pct(channelPercent(channel)) },
      }),

    /**
     * The house `div[role="slider"]`, unlike the area's native pair: a channel is
     * one tab stop with one value, which is exactly what the role describes, and
     * it already carries `data-engaged` for the pad.
     */
    getChannelSliderThumbProps: ({ channel }: ColorPickerChannelProps): T["element"] => {
      const range = getChannelRange(channel);
      const current = getChannelValue(color, channel);
      const text = channelValueText(channel);

      return normalize.element({
        ...parts.channelSliderThumb.attrs,
        ...stateAttrs,
        id: getChannelThumbId(scope, channel),
        role: "slider",
        // Dropped rather than set to -1: a disabled picker is out of the tab order
        // entirely, and a lone `tabindex="-1"` still answers a script's `.focus()`.
        tabIndex: disabled ? undefined : 0,
        "data-channel": channel,
        "data-orientation": "horizontal",
        "data-engaged": dataAttr(engagedTarget === channel),
        "data-dragging": dataAttr(activeChannel === channel && !engaged),
        // On every thumb, and the sheet's `:focus` picks the one that matters.
        //
        // This is the one place left in the repo that does not follow
        // architecture.md:51 ("un composite ne le pose que sur l'item focalisé").
        // The comment here used to call it "the `select:item` arrangement" — the
        // opposite is true: `select`, `listbox`, `menu`, `calendar`, `toggle-group`
        // and `slider` all gate it on the focused item, and the swatch below now
        // does too. The reason this one cannot is that `FOCUS.IN` carries no
        // channel, so the machine does not know *which* thumb has the focus, where
        // `slider` keeps a `focusedIndex`. Closing it means a payload and a piece
        // of state on a line already at 99% of its ceiling — named debt, measured,
        // not a shrug.
        "data-focus-source": focusSource ?? undefined,
        "aria-valuemin": range.min,
        "aria-valuemax": range.max,
        "aria-valuenow": roundToPrecision(current, 2),
        "aria-valuetext": text,
        "aria-orientation": "horizontal",
        ...channelNaming(channel),
        "aria-disabled": ariaAttr(disabled),
        "aria-readonly": ariaAttr(readOnly),
        style: {
          ...colorVars,
          "--sui-color-picker-channel-percent": pct(channelPercent(channel)),
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          const next = getChannelKeyEvent(event.key, channel, {
            dir: resolveDir(dir, getSurfaceEl(scope)),
            shiftKey: event.shiftKey,
          });
          // The interactive test sits before `preventDefault`, deliberately: on a
          // read-only picker PageDown still belongs to the page.
          if (next === null || !interactive) return;
          event.preventDefault();
          send(next);
        },
        onFocusIn() {
          send({ type: "FOCUS.IN" });
        },
        onFocusOut() {
          send({ type: "FOCUS.OUT" });
        },
      });
    },

    /**
     * A text field, never a `type="number"`: the hex channel is not a number, and
     * a spinner on the other seven would put a second pair of steppers next to a
     * slider that already has arrow keys.
     */
    getChannelInputProps: ({ channel }: ColorPickerInputProps): T["input"] => {
      const draft = drafts[channel];
      const shown =
        channel === "hex"
          ? toHex(color, alphaEnabled && color.a < 1)
          : String(displayValue(color, channel));

      return normalize.input({
        ...parts.channelInput.attrs,
        id: getChannelInputId(scope, channel),
        type: "text",
        inputMode: channel === "hex" ? "text" : "numeric",
        autoComplete: "off",
        spellCheck: false,
        disabled,
        readOnly,
        value: draft ?? shown,
        "data-channel": channel,
        // The *field* is invalid, not the component: the value has not moved.
        "data-invalid": dataAttr(invalidDrafts.includes(channel)),
        ...channelNaming(channel),
        onChange(event: Event) {
          const input = event.currentTarget as HTMLInputElement | null;
          if (input === null) return;
          send({ type: "INPUT.CHANGE", channel, text: input.value });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          if (event.key === "Enter") {
            event.preventDefault();
            send({ type: "INPUT.COMMIT", channel });
            return;
          }
          if (event.key === "Escape") {
            // The first Escape reverts the field, the second closes the surface.
            // The *veto* over the close lives in the dismissable layer's
            // `onEscapeKeyDown` — that listener is on the document in capture and
            // nothing here could get in front of it. This is the revert itself,
            // and it is what answers in `presentation="inline"`, where there is no
            // layer at all. Idempotent, so running twice costs nothing.
            event.stopPropagation();
            send({ type: "INPUT.REVERT", channel });
            return;
          }
          if (channel === "hex") return;
          if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
          event.preventDefault();
          send(
            event.key === "ArrowUp"
              ? { type: "CHANNEL.INCREMENT", channel, large: event.shiftKey }
              : { type: "CHANNEL.DECREMENT", channel, large: event.shiftKey },
          );
        },
        // Blur is an implicit commit — a Tab away must not silently discard what
        // was typed, which is the APG's answer for the same shape on a combobox.
        onFocusOut() {
          send({ type: "INPUT.COMMIT", channel });
          send({ type: "FOCUS.OUT" });
        },
        onFocusIn() {
          send({ type: "FOCUS.IN" });
        },
      });
    },

    /**
     * A real `<select>`: the one native control in the anatomy, because a format
     * switch is a four-item list with no styling worth a second machine. It is
     * excluded from the dismissable layer (§5.5) — its dropdown is painted by the
     * system, outside the DOM, and a click inside it reads as outside the surface.
     */
    getFormatSelectProps: (): T["select"] =>
      normalize.select({
        ...parts.formatSelect.attrs,
        id: getFormatSelectId(scope),
        "aria-label": translations?.formatSelectLabel ?? "Color format",
        disabled: disabled || readOnly,
        value: format,
        onChange(event: Event) {
          const element = event.currentTarget as HTMLSelectElement | null;
          if (element === null) return;
          send({ type: "FORMAT.SET", format: element.value as ColorFormat });
        },
      }),

    /**
     * `role="grid"`, not `role="listbox"`: the rows carry meaning — the
     * palette is a ramp of greys on row one and a hue × lightness matrix below it —
     * and the APG sends every interactive two-dimensional layout to
     * the Grid pattern. It is also what makes `Home`/`End` bounded to a row
     * coherent rather than a listbox wearing a grid's keyboard.
     */
    getSwatchGroupProps: (): T["element"] =>
      normalize.element({
        ...parts.swatchGroup.attrs,
        ...stateAttrs,
        id: getSwatchGroupId(scope),
        role: "grid",
        "aria-label": translations?.swatchGroupLabel ?? "Color swatches",
        "aria-readonly": ariaAttr(readOnly),
        "data-columns": swatchColumns,
        style: { "--sui-color-picker-columns": String(swatchColumns) },
      }),

    getSwatchRowProps: ({ row }: ColorPickerSwatchRowProps): T["element"] =>
      normalize.element({ ...parts.swatchRow.attrs, role: "row", "data-row": row }),

    getSwatchProps: ({ index }: ColorPickerSwatchProps): T["element"] => {
      const swatch = swatchList[index] ?? "transparent";
      const selected = index === selectedSwatch;

      return normalize.element({
        ...parts.swatch.attrs,
        id: getSwatchId(scope, index),
        role: "gridcell",
        tabIndex: disabled ? undefined : getRovingTabIndex(index, rovingSwatch),
        "aria-selected": boolAttr(selected),
        "aria-label": swatch,
        "data-value": swatch,
        "data-index": index,
        "data-selected": dataAttr(selected),
        "data-highlighted": dataAttr(index === highlighted),
        // On the roving cell alone — the one cell of the grid that can hold the
        // focus. It was on all of them until 2026-09-06, which is what
        // architecture.md:51 forbids in as many words ("un composite ne le pose que
        // sur l'item focalisé") and what `select`, `listbox`, `menu`, `calendar`,
        // `toggle-group` and `slider` all already do.
        "data-focus-source": index === rovingSwatch ? (focusSource ?? undefined) : undefined,
        style: { "--sui-color-picker-swatch-color": swatch },
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "SWATCH.HIGHLIGHT", index });
          send({ type: "SWATCH.SELECT", index });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.altKey || event.metaKey) return;
          if (event.key === "Enter") {
            event.preventDefault();
            if (!event.repeat) send({ type: "SWATCH.SELECT", index });
            return;
          }
          // Space activates on keyup — the APG split, and the defect this library
          // already found once on `tabs`.
          if (event.key === " ") {
            event.preventDefault();
            return;
          }
          const action = getGridKeyAction(event.key, {
            ctrlKey: event.ctrlKey,
            dir: resolveDir(dir, getSurfaceEl(scope)),
          });
          if (action === null) return;
          event.preventDefault();
          send({
            type: "SWATCH.HIGHLIGHT",
            index: getGridNextIndex(index, action, {
              count: swatchList.length,
              columns: swatchColumns,
              loop: prop("loopSwatches"),
              page: 1,
            }),
          });
        },
        onKeyUp(event) {
          if (event.defaultPrevented || event.key !== " ") return;
          event.preventDefault();
          send({ type: "SWATCH.SELECT", index });
        },
        onFocusIn() {
          send({ type: "FOCUS.IN" });
        },
        onFocusOut() {
          send({ type: "FOCUS.OUT" });
        },
      });
    },

    getSwatchIndicatorProps: ({ index }: ColorPickerSwatchProps): T["element"] =>
      normalize.element({
        ...parts.swatchIndicator.attrs,
        "aria-hidden": ariaAttr(true),
        "data-state": index === selectedSwatch ? "checked" : "unchecked",
      }),

    /**
     * The "+" button, and it lives **outside** the grid: a
     * `<button>` inside a `gridcell` is `nested-interactive`, which the APG
     * forbids and axe fails on.
     */
    getSwatchTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.swatchTrigger.attrs,
        type: "button",
        disabled: disabled || readOnly,
        "aria-label": translations?.swatchTriggerLabel ?? "Add current color",
        style: colorVars,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "SWATCH.ADD" });
        },
      }),

    getEyedropperTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.eyedropperTrigger.attrs,
        id: getEyedropperTriggerId(scope),
        type: "button",
        disabled: disabled || readOnly,
        "aria-label": translations?.eyedropperLabel ?? "Pick a color from the screen",
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "EYEDROPPER.OPEN" });
        },
      }),

    getTransparencyGridProps: (): T["element"] =>
      normalize.element({ ...parts.transparencyGrid.attrs, "aria-hidden": ariaAttr(true) }),
  };
}

/**
 * Only the parts something points at get an id: an `aria-labelledby`, an
 * `aria-controls`, a machine lookup, or a `.focus()`. The gradients, the
 * chequerboard and the swatch rows are referenced by nothing, and an id per
 * element nobody names is markup nobody reads.
 *
 * The channel parts are keyed by their channel name rather than by an index —
 * `hue` and `red` are never both on screen, but the format select can swap one
 * set for the other between two commits, and an index would silently re-point a
 * label at a different track.
 */

import { query, queryAll } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";
import type { ColorNumericChannel } from "../../utils/color";

const COMPONENT = "color-picker";

/** Written out rather than derived from the anatomy: a query should not pay for the builder. */
const CONTENT_SELECTOR = '[data-part~="color-picker:content"]';
export const CHANNEL_SLIDER_SELECTOR = '[data-part~="color-picker:channel-slider"]';
export const SWATCH_SELECTOR = '[data-part~="color-picker:swatch"]';

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getValueTextId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "value-text");
}

export function getHiddenInputId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "hidden-input");
}

export function getBackdropId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "backdrop");
}

export function getPositionerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "positioner");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getTitleId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "title");
}

export function getCancelTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "cancel-trigger");
}

export function getCloseTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "close-trigger");
}

export function getAreaId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "area");
}

export function getAreaXInputId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "area-x-input");
}

export function getAreaYInputId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "area-y-input");
}

export function getChannelLabelId(scope: Scope, channel: string): string {
  return getPartId(scope, COMPONENT, "channel-label", channel);
}

export function getChannelThumbId(scope: Scope, channel: string): string {
  return getPartId(scope, COMPONENT, "channel-slider-thumb", channel);
}

export function getChannelInputId(scope: Scope, channel: string): string {
  return getPartId(scope, COMPONENT, "channel-input", channel);
}

export function getFormatSelectId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "format-select");
}

export function getSwatchGroupId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "swatch-group");
}

export function getSwatchId(scope: Scope, index: number): string {
  return getPartId(scope, COMPONENT, "swatch", String(index));
}

export function getEyedropperTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "eyedropper-trigger");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

/** The floating element: what gets the translate, never the content. */
export function getPositionerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getPositionerId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

/** The gesture surface for the two-dimensional drag; the rect comes from here. */
export function getAreaEl(scope: Scope): HTMLElement | null {
  return scope.getById(getAreaId(scope));
}

export function getAreaXInputEl(scope: Scope): HTMLElement | null {
  return scope.getById(getAreaXInputId(scope));
}

export function getChannelThumbEl(scope: Scope, channel: ColorNumericChannel): HTMLElement | null {
  return scope.getById(getChannelThumbId(scope, channel));
}

export function getFormatSelectEl(scope: Scope): HTMLElement | null {
  return scope.getById(getFormatSelectId(scope));
}

export function getSwatchEl(scope: Scope, index: number): HTMLElement | null {
  return scope.getById(getSwatchId(scope, index));
}

export function getEyedropperTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getEyedropperTriggerId(scope));
}

export function getHiddenInputEl(scope: Scope): HTMLInputElement | null {
  return scope.getById<HTMLInputElement>(getHiddenInputId(scope));
}

/**
 * The surface in every presentation. `inline` renders the content in place with
 * no positioner and no portal, so the delegated pointer listeners and the intent
 * scopes have one element to hang on either way.
 */
export function getSurfaceEl(scope: Scope): HTMLElement | null {
  return getContentEl(scope) ?? getRootEl(scope);
}

/** This picker's own swatch cells, in DOM order — never another picker's. */
export function getSwatchEls(scope: Scope): HTMLElement[] {
  const surface = getSurfaceEl(scope);
  if (surface === null) return [];
  return queryAll<HTMLElement>(surface, SWATCH_SELECTOR).filter(
    (cell) => cell.closest(CONTENT_SELECTOR) === surface.closest(CONTENT_SELECTOR),
  );
}

/** Whether the real focus is inside this picker's surface — never a virtual one. */
export function ownsFocus(scope: Scope): boolean {
  const surface = getSurfaceEl(scope);
  const active = scope.getActiveElement();
  return surface !== null && active !== null && surface.contains(active);
}

/**
 * `aria-labelledby` may only point at an id that exists — the rule `slider`,
 * `progress` and `field` all follow, and the one an audit found broken in two
 * components because every fixture happened to render its label.
 */
export function hasPart(scope: Scope, part: string): boolean {
  return query(getRootEl(scope), `[data-part~="color-picker:${part}"]`) !== null;
}

/**
 * The same question, asked of the surface. `content` is portalled in `popup` and
 * `sheet`, so a query rooted on `root` cannot see the title or the channel labels
 * — and those are exactly the three parts an `aria-labelledby` points at.
 */
export function hasSurfacePart(scope: Scope, part: string): boolean {
  return query(getSurfaceEl(scope), `[data-part~="color-picker:${part}"]`) !== null;
}

/**
 * Which channels a label was actually rendered for — not *whether* any was. The
 * distinction is the whole defect: a panel that labels its three sliders and lets
 * the hex field take the library's own name is an ordinary composition, and a
 * global boolean answered "yes" for the hex field too, pointing its
 * `aria-labelledby` at an id nobody rendered. A dangling IDREF *and* a control with
 * no accessible name, in every story and in the SSR fixture (audit of 2026-09-05).
 *
 * The channel is read from the part's own `data-channel`, which it already carries.
 */
export function getLabelledChannels(scope: Scope): string[] {
  const labels = queryAll<HTMLElement>(
    getSurfaceEl(scope),
    `[data-part~="color-picker:channel-label"]`,
  );
  return labels
    .map((label) => label.getAttribute("data-channel"))
    .filter((channel): channel is string => channel !== null);
}

/** Same three fallbacks as the menu: no document, no throw. */
export function getEnvironmentEl(scope: Scope): HTMLElement | null {
  const rendered = getRootEl(scope) ?? getContentEl(scope) ?? getTriggerEl(scope);
  if (rendered !== null) return rendered;
  const root = scope.getRootNode();
  if (root === null) return null;
  return (root.ownerDocument ?? (root as Document)).documentElement;
}

/**
 * The colour picker: an overlay, a collection, a two-dimensional value control and
 * up to four one-dimensional ones, in a single machine.
 *
 * **Two states, and `engaged` is deliberately not a third.** The interpreter is
 * flat — `runTransition` tears down the exited state's effects before entering
 * the next one (`machine/service.ts`). The slider can afford `engaged` as a
 * sibling state because the state it leaves owns exactly one effect; here `open`
 * owns the dismissable layer, the position tracker, the focus trap, the scroll
 * lock and the `aria-hidden` sweep, and tearing those down to take hold of a knob
 * would pop the layer, re-fit the surface and hand the focus back to the trigger
 * in the middle of a gesture. So the hold is `context.engagedTarget` plus a scope
 * whose dispose lives in a ref, and `trackEngage` — an effect of `open` — is what
 * guarantees it is detached when the surface goes. Same guarantee, in the one
 * place that can survive the hold.
 *
 * **Events carry a ratio, never a coordinate** (the slider's rule): the pointer
 * effects hold the elements, so they do the conversion and every transition stays
 * reachable from a node test. The area sends two of them, one per axis.
 *
 * **HSVA is the context, sRGB is the view.** `utils/color` explains why, and
 * `anchorHue` is the reason a brightness dragged to zero and back comes up the
 * colour it went down as.
 */

import { getLiveAnnouncer } from "../../a11y/live-announcer";
import { getRowCount } from "../../collection/grid-collection";
import { addDomEvent } from "../../dom/event";
import { observeChildren } from "../../dom/observers";
import { timeout } from "../../dom/raf";
import { resolveDir } from "../../dom/text-dir";
import {
  resolveEnvironment,
  trackEnvironment as watchEnvironment,
} from "../../environment/environment";
import { isEscapeLikeDismissal } from "../../interaction/layer-stack";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams, Transition } from "../../machine/types";
import { focusElement, getInputModality, pushEngageScope, trackInputModality } from "../../nav";
import type { Density, Direction, InputModality } from "../../types";
import {
  anchorHue,
  type ColorNumericChannel,
  type ColorValue,
  colorEquals,
  formatColor,
  getChannelRange,
  getChannelValue,
  getColorName,
  hsvToRgb,
  parseColor,
  wrapHue,
} from "../../utils/color";
import { arrayEquals, shallowEqual } from "../../utils/equality";
import {
  getAreaXInputEl,
  getChannelThumbEl,
  getContentEl,
  getEnvironmentEl,
  getEyedropperTriggerEl,
  getHiddenInputEl,
  getLabelledChannels,
  getRootEl,
  getSurfaceEl,
  getSwatchEl,
  hasPart,
  hasSurfacePart,
} from "./color-picker.dom";
import { trackAreaPointer, trackChannelPointer } from "./color-picker.pointer";
import {
  getAreaAxis,
  resolveDirection,
  toAreaAdjustEvent,
  toChannelAdjustEvent,
} from "./color-picker.props";
import {
  captureSurfaceIntents,
  hideOutside,
  lockPageScroll,
  trackAnchorPosition,
  trackDismissable,
  trackFocusTrap,
  trackSurfaceDir,
} from "./color-picker.surface";
import type { ColorPickerEngageTarget, ColorPickerSchema } from "./color-picker.types";
import {
  applyString,
  FALLBACK,
  focusedEngageTarget,
  strideOf,
  writeArea,
  writeChannel,
  writeColor,
} from "./color-picker.value";

// A controlled getter still returns the parent's string until it answers, so
// the report reads the write itself; consumed even with no callback to call.
// A colour the parent already holds goes back as the parent's own string: the
// formatted one is a different spelling of it, and a parent that re-parses what
// it is told would drift off its colour on every gesture that ended where it began.
// The colour held is the cell's own, which carries the hue a grey or a black
// cannot spell; the string only has to be one the picker can read, since an
// unreadable or stale one leaves the cell on a colour it no longer describes.
// The module's write is dropped once it is no longer the prop: a detection that
// answers late must not bring back a part the prop has taken away.
const detectModule = (params: MachineParams<ColorPickerSchema>): void => {
  const { context, prop, refs } = params;
  const module = prop("eyedropper");
  const set: typeof context.set = (key, value) => {
    if (prop("eyedropper") === module) context.set(key, value);
  };
  refs.set("eyedropperEnd", module?.detect({ ...params, context: { ...context, set } }) ?? null);
};

const endModule = ({ refs }: MachineParams<ColorPickerSchema>): void => {
  refs.get("eyedropperEnd")?.();
  refs.set("eyedropperEnd", null);
};

const reportEnd = ({ context, refs, prop }: MachineParams<ColorPickerSchema>): void => {
  const color = refs.get("changed") ?? context.get("color");
  refs.set("changed", null);
  const held = prop("value") ?? "";
  const value =
    parseColor(held) !== null && colorEquals(color, context.get("color"))
      ? held
      : formatColor(color, context.get("format"));
  prop("onValueChangeEnd")?.({ value, color });
};

/**
 * Outside a hold every adjustment *is* the whole gesture and reports on the spot;
 * inside one the hold is the gesture and `CHANNEL.RELEASE` is its only end — so
 * A, →, →, B reports once rather than three times. The slider's arrangement, with
 * a guard where it has a state.
 */
const CHANNEL_ADJUST: Transition<ColorPickerSchema> = [
  { guard: "isEngaged", actions: ["adjustChannel"] },
  { guard: "isInteractive", actions: ["adjustChannel", "invokeChangeEnd"] },
];

const CHANNEL_EXTREME: Transition<ColorPickerSchema> = [
  { guard: "isEngaged", actions: ["setChannelExtreme"] },
  { guard: "isInteractive", actions: ["setChannelExtreme", "invokeChangeEnd"] },
];

const AREA_ADJUST: Transition<ColorPickerSchema> = [
  { guard: "isEngaged", actions: ["adjustArea"] },
  { guard: "isInteractive", actions: ["adjustArea", "invokeChangeEnd"] },
];

const AREA_EXTREME: Transition<ColorPickerSchema> = [
  { guard: "isEngaged", actions: ["setAreaExtreme"] },
  { guard: "isInteractive", actions: ["setAreaExtreme", "invokeChangeEnd"] },
];

export const machine: Machine<ColorPickerSchema> = createMachine<ColorPickerSchema>({
  props({ props }) {
    return {
      defaultValue: "#000000",
      defaultFormat: "hex",
      formats: ["hex", "rgb", "hsl", "hsb"],
      alpha: true,
      defaultOpen: false,
      presentation: "auto",
      placement: "bottom-start",
      gap: 4,
      offset: 0,
      flip: true,
      shift: true,
      padding: 8,
      strategy: "fixed",
      closeOnEscape: true,
      closeOnInteractOutside: true,
      restoreFocus: true,
      disabled: false,
      readOnly: false,
      invalid: false,
      required: false,
      variant: "well",
      step: 1,
      swatches: [],
      maxSwatches: 12,
      loopSwatches: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable, getContext }) {
    // The controlled string is parsed once per distinct value rather than on every
    // read: `createBindable` re-invokes this factory's `init` on each `get`, and a
    // regex per read of a colour is a cost with no reason. The anchor is the last
    // colour the parent confirmed — a parse, or an emission it handed back or
    // already held — which for a controlled picker is the context itself.
    const declaredDefault = (): ColorValue => parseColor(prop("defaultValue")) ?? FALLBACK;
    let lastRaw: string | undefined;
    let lastParsed: ColorValue | undefined;
    // The string folds what the object keeps (a hue of 360 reads back as 0), so
    // the emitted colour is held apart and adopted when the parent's string is
    // the one that was sent — handed back, or already held; a read in between
    // still sees the parent's own.
    let sent: string | undefined;
    let sentColor: ColorValue | undefined;
    const controlledColor = (): ColorValue | undefined => {
      const raw = prop("value");
      if (raw === undefined) return undefined;
      if (raw === sent) {
        lastRaw = raw;
        lastParsed = sentColor;
        sent = undefined;
      } else if (raw !== lastRaw) {
        lastRaw = raw;
        sent = undefined;
        const parsed = parseColor(raw);
        lastParsed =
          parsed === null ? lastParsed : anchorHue(parsed, lastParsed ?? declaredDefault());
      }
      return lastParsed;
    };

    return {
      color: bindable<ColorValue>(() => ({
        defaultValue: declaredDefault(),
        value: controlledColor(),
        // Without this every write of a fresh object — which is every write —
        // would report a change and re-render, forever.
        isEqual: colorEquals,
        onChange: (color) => {
          const value = formatColor(color, getContext().get("format"));
          sent = value;
          sentColor = color;
          prop("onValueChange")?.({ value, color });
        },
        debugLabel: "color-picker color",
      })),
      open: bindable<boolean>(() => ({
        // `inline` has no surface to close, so its openness is not a decision.
        defaultValue: prop("presentation") === "inline" ? true : prop("defaultOpen"),
        value: prop("presentation") === "inline" ? true : prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "color-picker open",
      })),
      format: bindable(() => ({
        defaultValue: prop("defaultFormat"),
        value: prop("format"),
        onChange: (format) => prop("onFormatChange")?.({ format }),
        debugLabel: "color-picker format",
      })),
      activeChannel: bindable<ColorPickerEngageTarget | null>(() => ({ defaultValue: null })),
      engagedTarget: bindable<ColorPickerEngageTarget | null>(() => ({ defaultValue: null })),
      areaDragging: bindable<boolean>(() => ({ defaultValue: false })),
      highlightedSwatch: bindable<number>(() => ({ defaultValue: -1 })),
      savedSwatches: bindable<string[]>(() => ({ defaultValue: [], isEqual: arrayEquals })),
      density: bindable<Density>(() => ({ defaultValue: "desktop" })),
      surfaceDir: bindable<Direction | null>(() => ({ defaultValue: null })),
      currentPlacement: bindable(() => ({ defaultValue: prop("placement") })),
      eyedropperSupported: bindable<boolean>(() => ({ defaultValue: false })),
      inputDrafts: bindable<Record<string, string>>(() => ({
        defaultValue: {},
        isEqual: shallowEqual,
      })),
      invalidDrafts: bindable<string[]>(() => ({ defaultValue: [], isEqual: arrayEquals })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
      hasTitle: bindable<boolean>(() => ({ defaultValue: false })),
      hasValueText: bindable<boolean>(() => ({ defaultValue: false })),
      labelledChannels: bindable<string[]>(() => ({ defaultValue: [], isEqual: arrayEquals })),
    };
  },

  computed: {
    presentation({ prop, context }) {
      const requested = prop("presentation");
      if (requested !== "auto") return requested;
      return context.get("density") === "touch" ? "sheet" : "popup";
    },
    isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    // `inline` has nothing to trap and nothing to close, so `modal` cannot reach it.
    isModal({ prop, computed }) {
      const presentation = computed("presentation");
      return presentation !== "inline" && (prop("modal") ?? presentation === "sheet");
    },
    valueString: ({ context }) => formatColor(context.get("color"), context.get("format")),
    rgb: ({ context }) => hsvToRgb(context.get("color")),
    /**
     * The tracks that are drawn, in tab order. `rgb` shows its three channels;
     * every other format shows the hue, because the area already *is* the
     * saturation and the brightness and a second copy of them is furniture.
     */
    channels({ prop, context }) {
      const base: ColorNumericChannel[] =
        context.get("format") === "rgb" ? ["red", "green", "blue"] : ["hue"];
      return prop("alpha") ? [...base, "alpha"] : base;
    },
    swatchList: ({ prop, context }) =>
      [...prop("swatches"), ...context.get("savedSwatches")].slice(0, prop("maxSwatches")),
    swatchColumns: ({ prop, context }) =>
      prop("swatchColumns") ?? (context.get("density") === "touch" ? 6 : 12),
    swatchRows: ({ computed }) =>
      getRowCount(computed("swatchList").length, computed("swatchColumns")),
    colorName: ({ context }) => getColorName(context.get("color")),
  },

  refs({ prop }) {
    return {
      entryColor: null,
      openColor: null,
      changed: null,
      finalFocusEl: null,
      engageDispose: null,
      eyedropperAbort: null,
      eyedropperEnd: null,
      initialValue: prop("value") ?? prop("defaultValue"),
    };
  },

  // Pure: no DOM, no environment. `inline` is open from the first byte the server
  // writes, which is what makes its hydration deterministic.
  initialState({ prop }) {
    if (prop("presentation") === "inline") return "open";
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: [
    "trackEnvironment",
    "trackModality",
    "trackParts",
    "trackFormReset",
    "detectEyedropper",
  ],

  watch({ context, computed, prop, scope, track, send, action }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
    track(
      () => [computed("presentation")],
      () => send({ type: "PRESENTATION.SYNC" }),
    );
    // The surface is portalled, so its parts are a watch dependency like any
    // other: a title and a set of channel labels that mount with the panel are
    // re-read on the adapter's next commit rather than one mutation record later.
    track(
      // The channels are joined rather than counted: a boolean stayed `true` when a
      // second label mounted beside the first, and the set behind it went stale.
      () => [
        hasPart(scope, "label"),
        hasSurfacePart(scope, "title"),
        getLabelledChannels(scope).join(" "),
      ],
      () => action(["syncParts"]),
    );
    track(
      () => [prop("eyedropper")],
      () => action(["syncEyedropper"]),
    );
  },

  on: {
    "VALUE.SET": { guard: "isInteractive", actions: ["setValueFromString", "invokeChangeEnd"] },
    "CHANNEL.SET": { guard: "isInteractive", actions: ["setChannelValue", "invokeChangeEnd"] },
    "FORMAT.SET": { actions: ["setFormat", "clearDrafts"] },
    "OPEN.SET": { actions: ["setOpen"] },
    "OPEN.SYNC": [{ guard: "isOpen", target: "open" }, { target: "closed" }],
    // The density flip tears the open state down and builds it back: the position
    // tracker leaves, the scroll lock arrives, the geometry changes.
    "PRESENTATION.SYNC": { guard: "isOpen", target: "open", reenter: true },
    "POSITION.SYNC": { actions: ["syncPlacement"] },
    "ENVIRONMENT.SYNC": { actions: ["syncEnvironment"] },
    "PARTS.SYNC": { actions: ["syncParts"] },
    "FORM.RESET": { actions: ["resetToInitialValue"] },
    "FOCUS.IN": { actions: ["captureFocusSource"] },
    /**
     * A Tab out of a held control ends the hold by committing. We do not trap the
     * focus inside an engage: somebody who tabs wants to leave, and losing their
     * value on the way would be a surprise. B stays the only cancel.
     */
    "FOCUS.OUT": [
      {
        guard: "isEngaged",
        actions: ["releaseTarget", "clearSnapshot", "invokeChangeEnd", "clearFocusSource"],
      },
      { actions: ["clearFocusSource"] },
    ],
  },

  states: {
    closed: {
      // Exit rather than the open state's entry, for the menu's reason: the
      // interpreter installs effects before entry actions, and an effect that
      // hides or moves things would blur the trigger before it was captured.
      exit: ["captureFinalFocus"],
      on: {
        "TRIGGER.CLICK": { guard: "isInteractive", actions: ["openSurface"] },
      },
    },

    open: {
      /**
       * The snapshot is taken on entry and read on the way out. It is deliberately
       * *not* cleared on exit: the interpreter runs a state's exit actions before
       * the transition's own, so an exit that cleared it would erase the value the
       * cancel is there to restore. A hold takes its own (`entryColor`), so the
       * cancel still puts back the colour the surface opened with (R36).
       */
      entry: ["snapshotOpenColor"],
      effects: [
        "trackSurfaceDir",
        "trackDismissable",
        "lockPageScroll",
        // Before anything that moves the focus: a focus landing in a surface
        // still parked at `0,0` scrolls the page there to reveal it.
        "trackAnchorPosition",
        "trackFocusTrap",
        "hideOutside",
        "captureSurfaceIntents",
        "captureSelectIntent",
        "trackEngage",
        "trackAreaPointer",
        "trackChannelPointer",
      ],
      on: {
        "TRIGGER.CLICK": { actions: ["closeSurface"] },
        "CONTENT.DISMISS": [
          // Decision 68: during a hold, Escape does what B does — it lets the hold
          // go to its start and the surface stays. Under a `NavProvider` mounted
          // first, the engage scope eats the key before the layer sees it; this
          // branch gives the same answer when the layer's listener runs first.
          {
            guard: ({ context, event }) =>
              context.get("engagedTarget") !== null &&
              event.type === "CONTENT.DISMISS" &&
              event.reason === "escape",
            actions: ["releaseTarget", "restoreEntryColor", "invokeChangeEnd"],
          },
          // In a sheet, outside a hold, Escape and B are the cancel's doubles. The
          // backdrop, and a popup that has no cancel, keep the colour.
          {
            guard: ({ computed, event, prop }) =>
              computed("presentation") === "sheet" &&
              event.type === "CONTENT.DISMISS" &&
              (event.reason === "escape" || event.reason === "back") &&
              prop("closeOnEscape"),
            actions: ["restoreOpenColor", "invokeChangeEnd", "invokeOnDismiss", "closeSurface"],
          },
          { guard: "canDismiss", actions: ["invokeOnDismiss", "closeSurface"] },
        ],
        // The touch twin of B: it puts the colour back and then leaves. It ends a
        // hold itself: a parent holding `open` can keep the surface, and the hold
        // left running would put its start back over the cancel on the next B.
        "CANCEL.CLICK": {
          actions: [
            "releaseTarget",
            "restoreOpenColor",
            "invokeChangeEnd",
            "invokeOnDismiss",
            "closeSurface",
          ],
        },
        "CLOSE.CLICK": { actions: ["closeSurface"] },

        "AREA.PRESS": {
          guard: "isInteractive",
          // `focusAreaInput` last, and it has to be: moving the focus fires a
          // synchronous `focus` event whose handler re-enters the machine and
          // replaces the event the actions still to run were reading.
          actions: ["startAreaDrag", "setAreaFromPoint", "focusAreaInput"],
        },
        "AREA.DRAG": { guard: "isAreaDragging", actions: ["setAreaFromPoint"] },
        // No `isInteractive` guard on purpose: a control that goes disabled
        // halfway through a gesture still has to finish it cleanly.
        "AREA.DRAG_END": { actions: ["endAreaDrag", "invokeChangeEnd"] },
        "AREA.SET": { guard: "isInteractive", actions: ["setAreaAxis", "invokeChangeEnd"] },
        "AREA.ADJUST": AREA_ADJUST,
        "AREA.SET_EXTREME": AREA_EXTREME,

        "CHANNEL.PRESS": {
          guard: "isInteractive",
          actions: ["startChannelDrag", "setChannelFromPercent", "focusChannelThumb"],
        },
        "CHANNEL.DRAG": { guard: "isChannelDragging", actions: ["setChannelFromPercent"] },
        "CHANNEL.DRAG_END": { actions: ["endChannelDrag", "invokeChangeEnd"] },
        "CHANNEL.INCREMENT": CHANNEL_ADJUST,
        "CHANNEL.DECREMENT": CHANNEL_ADJUST,
        "CHANNEL.SET_MIN": CHANNEL_EXTREME,
        "CHANNEL.SET_MAX": CHANNEL_EXTREME,

        "CHANNEL.ENGAGE": { guard: "canEngage", actions: ["snapshotColor", "engageTarget"] },
        "CHANNEL.RELEASE": [
          {
            guard: ({ event }) => event.type === "CHANNEL.RELEASE" && event.committed,
            actions: ["releaseTarget", "clearSnapshot", "invokeChangeEnd"],
          },
          { actions: ["releaseTarget", "restoreEntryColor", "invokeChangeEnd"] },
        ],

        "INPUT.CHANGE": { actions: ["setDraft"] },
        "INPUT.COMMIT": { guard: "isInteractive", actions: ["commitDraft"] },
        "INPUT.REVERT": { actions: ["clearDraft"] },

        "SWATCH.SELECT": { guard: "isInteractive", actions: ["selectSwatch", "invokeChangeEnd"] },
        "SWATCH.HIGHLIGHT": { actions: ["highlightSwatch"] },
        "SWATCH.ADD": { guard: "isInteractive", actions: ["saveCurrentSwatch"] },

        "EYEDROPPER.OPEN": { guard: "canEyedrop", actions: ["openEyedropper"] },
        "EYEDROPPER.RESULT": { actions: ["applyEyedropper", "invokeChangeEnd"] },
        // A cancelled gesture writes nothing, reports nothing and announces
        // nothing — an Escape during the pick is not an event to narrate.
        "EYEDROPPER.DISMISS": { actions: ["clearEyedropper"] },
      },
    },
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
      isOpen: ({ context }) => context.get("open"),
      isAreaDragging: ({ context }) => context.get("areaDragging"),
      isChannelDragging: ({ context }) => {
        const active = context.get("activeChannel");
        return active !== null && active !== "area" && context.get("engagedTarget") === null;
      },
      isEngaged: ({ context, prop }) =>
        context.get("engagedTarget") !== null && !prop("disabled") && !prop("readOnly"),
      // The slider's guard, copied: a pad that is not wired cannot take hold.
      canEngage: ({ prop }) => !prop("disabled") && !prop("readOnly") && prop("intents") !== null,
      canEyedrop: ({ prop, context }) =>
        context.get("eyedropperSupported") && !prop("disabled") && !prop("readOnly"),

      /** Read live from the props, never snapshotted into the layer at install. */
      canDismiss({ prop, computed, event }) {
        if (computed("presentation") === "inline") return false;
        if (event.type !== "CONTENT.DISMISS") return false;
        if (isEscapeLikeDismissal(event.reason)) return prop("closeOnEscape");
        return prop("closeOnInteractOutside");
      },
    },

    actions: {
      openSurface({ context }) {
        context.set("open", true);
      },

      closeSurface({ context, prop }) {
        if (prop("presentation") === "inline") return;
        context.set("open", false);
      },

      setOpen({ context, prop, event }) {
        if (event.type !== "OPEN.SET" || prop("presentation") === "inline") return;
        context.set("open", event.open);
      },

      captureFinalFocus({ refs, scope }) {
        const active = scope.getActiveElement();
        refs.set("finalFocusEl", active === null || active.tagName === "BODY" ? null : active);
      },

      snapshotColor({ context, refs }) {
        refs.set("entryColor", context.get("color"));
        refs.set("changed", null);
      },

      snapshotOpenColor({ context, refs }) {
        refs.set("openColor", context.get("color"));
        refs.set("changed", null);
      },

      restoreOpenColor(params) {
        const open = params.refs.get("openColor");
        if (open !== null) writeColor(params, open);
      },

      restoreEntryColor(params) {
        const entry = params.refs.get("entryColor");
        params.refs.set("entryColor", null);
        if (entry !== null) writeColor(params, entry);
        else params.refs.set("changed", null);
      },

      clearSnapshot({ refs }) {
        refs.set("entryColor", null);
      },

      startAreaDrag({ context }) {
        context.set("areaDragging", true);
        context.set("activeChannel", "area");
      },

      endAreaDrag({ context }) {
        context.set("areaDragging", false);
        if (context.get("engagedTarget") === null) context.set("activeChannel", null);
      },

      setAreaFromPoint(params) {
        const { event } = params;
        if (event.type !== "AREA.PRESS" && event.type !== "AREA.DRAG") return;
        writeArea(params, event.x, event.y);
      },

      /** The `change` a real `<input type="range">` fires when a reader pushes a value. */
      setAreaAxis(params) {
        const { event } = params;
        if (event.type !== "AREA.SET") return;
        writeChannel(params, event.axis === "x" ? "saturation" : "brightness", event.value);
      },

      adjustArea(params) {
        const { event, prop, context } = params;
        if (event.type !== "AREA.ADJUST") return;
        const channel: ColorNumericChannel = event.axis === "x" ? "saturation" : "brightness";
        const stride = strideOf(prop, channel, event.large);
        const current = getChannelValue(context.get("color"), channel);
        writeChannel(
          params,
          channel,
          current + (event.direction === "decrement" ? -stride : stride),
        );
      },

      setAreaExtreme(params) {
        const { event } = params;
        if (event.type !== "AREA.SET_EXTREME") return;
        const channel: ColorNumericChannel = event.axis === "x" ? "saturation" : "brightness";
        const range = getChannelRange(channel);
        writeChannel(params, channel, event.edge === "min" ? range.min : range.max);
      },

      focusAreaInput({ scope, event }) {
        if (event.type === "AREA.PRESS") focusElement(getAreaXInputEl(scope));
      },

      startChannelDrag({ context, event }) {
        if (event.type === "CHANNEL.PRESS") context.set("activeChannel", event.channel);
      },

      endChannelDrag({ context }) {
        if (context.get("engagedTarget") === null) context.set("activeChannel", null);
      },

      setChannelFromPercent(params) {
        const { event, context } = params;
        if (event.type !== "CHANNEL.PRESS" && event.type !== "CHANNEL.DRAG") return;
        const active =
          event.type === "CHANNEL.PRESS" ? event.channel : context.get("activeChannel");
        if (active === null || active === "area") return;
        const range = getChannelRange(active);
        writeChannel(params, active, range.min + event.percent * (range.max - range.min));
      },

      setChannelValue(params) {
        const { event } = params;
        if (event.type !== "CHANNEL.SET") return;
        writeChannel(params, event.channel, event.value);
      },

      /**
       * Hue is the one circular channel: `359 + 1` is `0` rather than a value the
       * clamp would have held still at. Every other channel clamps.
       */
      adjustChannel(params) {
        const { event, prop, context } = params;
        if (event.type !== "CHANNEL.INCREMENT" && event.type !== "CHANNEL.DECREMENT") return;
        const stride = strideOf(prop, event.channel, event.large);
        const current = getChannelValue(context.get("color"), event.channel);
        const next = current + (event.type === "CHANNEL.DECREMENT" ? -stride : stride);
        writeChannel(params, event.channel, event.channel === "hue" ? wrapHue(next) : next);
      },

      setChannelExtreme(params) {
        const { event } = params;
        if (event.type !== "CHANNEL.SET_MIN" && event.type !== "CHANNEL.SET_MAX") return;
        const range = getChannelRange(event.channel);
        writeChannel(
          params,
          event.channel,
          event.type === "CHANNEL.SET_MIN" ? range.min : range.max,
        );
      },

      // APG: pressing anywhere on a track moves the value *and* the focus, so the
      // arrow keys carry on from where the pointer left off.
      focusChannelThumb({ scope, event }) {
        if (event.type === "CHANNEL.PRESS") focusElement(getChannelThumbEl(scope, event.channel));
      },

      /**
       * The pad's hold on the value. `pushEngageScope` consumes `back`, so B puts
       * the entry colour back instead of popping the layer underneath — a picker
       * whose B closed the surface on the way out of a channel would be unusable.
       */
      engageTarget(params) {
        const { prop, context, refs, scope, send, event } = params;
        if (event.type !== "CHANNEL.ENGAGE") return;
        const host = prop("intents");
        if (host === null) return;
        refs.get("engageDispose")?.();
        context.set("engagedTarget", event.target);
        context.set("activeChannel", event.target);
        refs.set(
          "engageDispose",
          pushEngageScope(host, {
            onAdjust: (intent) => {
              const target = context.get("engagedTarget");
              if (target === null) return;
              const dir = resolveDir(prop("dir"), getSurfaceEl(scope));
              const adjustment = resolveDirection(intent, dir);
              send(
                target === "area"
                  ? toAreaAdjustEvent(adjustment, getAreaAxis(intent))
                  : toChannelAdjustEvent(adjustment, target),
              );
            },
            onRelease: (committed) => {
              // The scope has already popped itself; dropping the handle here is
              // what keeps `releaseTarget` from popping a second time.
              refs.set("engageDispose", null);
              send({ type: "CHANNEL.RELEASE", committed });
            },
          }),
        );
      },

      releaseTarget({ context, refs }) {
        refs.get("engageDispose")?.();
        refs.set("engageDispose", null);
        context.set("engagedTarget", null);
        context.set("activeChannel", null);
      },

      setDraft({ context, event }) {
        if (event.type !== "INPUT.CHANGE") return;
        context.set("inputDrafts", { ...context.get("inputDrafts"), [event.channel]: event.text });
      },

      /**
       * Unparsable text leaves the colour alone and marks **the field**, not the
       * component: `invalid` is a statement about the value, and the value has not
       * moved. The draft survives so the user can fix what they typed.
       */
      commitDraft(params) {
        const { context, event } = params;
        if (event.type !== "INPUT.COMMIT") return;
        const channel = event.channel;
        const drafts = context.get("inputDrafts");
        const text = drafts[channel];
        if (text === undefined) return;

        const invalid = context.get("invalidDrafts");
        const accept = (): void => {
          const { [channel]: _dropped, ...rest } = drafts;
          context.set("inputDrafts", rest);
          if (invalid.includes(channel)) {
            context.set(
              "invalidDrafts",
              invalid.filter((name) => name !== channel),
            );
          }
          reportEnd(params);
        };
        const reject = (): void => {
          if (!invalid.includes(channel)) context.set("invalidDrafts", [...invalid, channel]);
        };

        if (channel === "hex") {
          if (parseColor(text) === null) {
            reject();
            return;
          }
          applyString(params, text);
          accept();
          return;
        }

        const typed = text.trim().replace(/%$/, "");
        const value = Number(typed);
        if (typed === "" || !Number.isFinite(value)) {
          reject();
          return;
        }
        // The opacity field is in per cent ("100 %"),
        // while the channel itself runs 0…1 — so the field's unit is converted
        // here rather than leaking a second scale into `withChannel`.
        writeChannel(params, channel, channel === "alpha" ? value / 100 : value);
        accept();
      },

      clearDraft({ context, event }) {
        if (event.type !== "INPUT.REVERT") return;
        const { [event.channel]: _dropped, ...rest } = context.get("inputDrafts");
        context.set("inputDrafts", rest);
        context.set(
          "invalidDrafts",
          context.get("invalidDrafts").filter((name) => name !== event.channel),
        );
      },

      /**
       * A format change swaps the list of fields on screen, so a draft still
       * holding "255" would land on a channel that now means `H`. They are wiped
       * rather than kept: a silently wrong value at the next blur is worse than a
       * retyped one.
       */
      clearDrafts({ context }) {
        context.set("inputDrafts", {});
        context.set("invalidDrafts", []);
      },

      setFormat({ context, event }) {
        if (event.type === "FORMAT.SET") context.set("format", event.format);
      },

      selectSwatch(params) {
        const { computed, event } = params;
        if (event.type !== "SWATCH.SELECT") return;
        const value = computed("swatchList")[event.index];
        if (value === undefined) return;
        applyString(params, value);
      },

      highlightSwatch({ context, scope, event }) {
        if (event.type !== "SWATCH.HIGHLIGHT") return;
        context.set("highlightedSwatch", event.index);
        if (event.index >= 0) focusElement(getSwatchEl(scope, event.index));
      },

      /**
       * The most recent colours win: the panel is a list of what was just used,
       * so a full one drops its oldest rather than refusing the new one.
       */
      saveCurrentSwatch({ context, computed, prop }) {
        const value = computed("valueString");
        const saved = context.get("savedSwatches");
        const provided = prop("swatches");
        if (provided.includes(value) || saved.includes(value)) return;
        const room = Math.max(prop("maxSwatches") - provided.length, 0);
        if (room === 0) return;
        const next = [...saved, value];
        context.set("savedSwatches", next.slice(Math.max(next.length - room, 0)));
      },

      openEyedropper: (params) => params.prop("eyedropper")?.open(params),

      /**
       * The module is a prop, so it can come, go or change after the mount; the
       * effect that first asked it only ran once. The outgoing module's disposer
       * runs, support is asked again, and a pick left without a module — or on an
       * engine that has none — is called off while the trigger is still in the
       * document, so the focus it held moves to the area (the panel itself where
       * there is none) rather than falling to `body` with the part.
       */
      syncEyedropper(params) {
        const { context, prop, refs, scope } = params;
        endModule(params);
        detectModule(params);
        if (prop("eyedropper") === undefined) context.set("eyedropperSupported", false);
        if (context.get("eyedropperSupported")) return;
        refs.get("eyedropperAbort")?.abort();
        refs.set("eyedropperAbort", null);
        if (scope.isActiveElement(getEyedropperTriggerEl(scope))) {
          focusElement(getAreaXInputEl(scope) ?? getContentEl(scope));
        }
      },

      /**
       * The one place this component announces anything. Every other value lives
       * on a `role="slider"` or an `<input type="range">` that publishes it
       * already; a screen pick changes the colour while nothing is focused, so
       * without this it changes in silence.
       */
      applyEyedropper(params) {
        const { event, scope, refs, context } = params;
        if (event.type !== "EYEDROPPER.RESULT") return;
        applyString(params, event.sRGBHex);
        if (scope.getRootNode() === null) return;
        getLiveAnnouncer(scope.getDoc()).announce(
          `${getColorName(refs.get("changed") ?? context.get("color"))} selected`,
          "polite",
        );
      },

      /**
       * The focus went to the screen picker's own overlay and comes back to the
       * button that opened it — the place a user who pressed Escape expects to be.
       */
      clearEyedropper({ refs, scope }) {
        refs.set("eyedropperAbort", null);
        focusElement(getEyedropperTriggerEl(scope));
      },

      // Read once, when focus lands, and held: the modality of *now* flips to
      // pointer after 300 ms of mouse movement whether or not the focus moved, and
      // a ring that blinks out under the user's hands was the result.
      captureFocusSource({ context, scope }) {
        if (scope.getRootNode() === null) return;
        context.set("focusSource", getInputModality(scope.getDoc()));
      },

      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },

      setValueFromString(params) {
        const { event } = params;
        if (event.type !== "VALUE.SET") return;
        applyString(params, event.value);
      },

      resetToInitialValue(params) {
        applyString(params, params.refs.get("initialValue"));
        params.refs.set("changed", null);
      },

      invokeChangeEnd: reportEnd,

      invokeOnDismiss({ prop, event }) {
        prop("onDismiss")?.({ reason: event.type === "CONTENT.DISMISS" ? event.reason : "back" });
      },

      syncEnvironment({ context, event }) {
        if (event.type === "ENVIRONMENT.SYNC") context.set("density", event.density);
      },

      syncPlacement({ context, event }) {
        if (event.type === "POSITION.SYNC") context.set("currentPlacement", event.placement);
      },

      syncParts({ context, scope }) {
        context.set("hasLabel", hasPart(scope, "label"));
        context.set("hasTitle", hasSurfacePart(scope, "title"));
        context.set("hasValueText", hasPart(scope, "value-text"));
        context.set("labelledChannels", getLabelledChannels(scope));
      },
    },

    effects: {
      trackEnvironment({ scope, send }) {
        const node = getEnvironmentEl(scope);
        const onChange = (density: Density): void => send({ type: "ENVIRONMENT.SYNC", density });
        onChange(resolveEnvironment(node).density);
        return watchEnvironment(node, {
          onChange: (environment) => onChange(environment.density),
        });
      },

      // No listener: the source is read once, when focus lands. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        return observeChildren(getRootEl(scope), () => send({ type: "PARTS.SYNC" }));
      },

      /**
       * The native `reset` runs first (`timeout 0`), then the machine follows it —
       * so the hidden input and the swatch agree with the form instead of racing it.
       */
      trackFormReset({ scope, send }) {
        const mirror = getHiddenInputEl(scope);
        const form = mirror?.form ?? null;
        const win = form?.ownerDocument.defaultView ?? null;
        if (form === null || win === null) return;
        let cancel: VoidFunction | null = null;
        const remove = addDomEvent(form, "reset", () => {
          cancel?.();
          cancel = timeout(
            win,
            () => {
              cancel = null;
              send({ type: "FORM.RESET" });
            },
            0,
          );
        });
        return () => {
          cancel?.();
          remove();
        };
      },

      // Opt-in: the module lives at its own sub-path (`./eyedropper`), and a
      // picker handed none never looks for an `EyeDropper` at all. The disposer
      // is held in a ref that `syncEyedropper` shares, so whichever module is
      // current when the picker stops is the one that is ended.
      detectEyedropper(params) {
        detectModule(params);
        return () => endModule(params);
      },

      trackSurfaceDir,
      trackDismissable,
      lockPageScroll,
      trackAnchorPosition,
      trackFocusTrap,
      hideOutside,
      captureSurfaceIntents,

      /**
       * A is how a pad takes hold. Never from a keyboard: Enter belongs to the form
       * around the picker, the arrows already move the value without holding
       * anything, and a keyboard engage would hand Escape the power to rewind a
       * value the user had settled on.
       */
      captureSelectIntent(params) {
        const { prop, send } = params;
        const host = prop("intents");
        if (host === null) return;
        return host.pushScope(
          (event) => {
            if (event.intent !== "select" || event.source === "keyboard") return false;
            if (prop("disabled") || prop("readOnly")) return false;
            const target = focusedEngageTarget(params);
            if (target === null) return false;
            send({ type: "CHANNEL.ENGAGE", target });
            return true;
          },
          { within: () => getSurfaceEl(params.scope) },
        );
      },

      /**
       * The hold's teardown, and the reason `engaged` does not need to be a state.
       * `pushEngageScope`'s dispose detaches silently — unmounting a picker is not
       * the user letting go, so `onRelease` does not fire here.
       */
      trackEngage({ context, refs }) {
        return () => {
          refs.get("engageDispose")?.();
          refs.set("engageDispose", null);
          refs.set("changed", null);
          context.set("engagedTarget", null);
          context.set("activeChannel", null);
        };
      },

      trackAreaPointer,
      trackChannelPointer,
    },
  },
});

/**
 * The gesture half of the machine's effects, in a module of its own.
 *
 * Not a second component and not a barrel — the folder's own `index.ts` is still
 * the only one. The picker carries two pointer paths and no other component has
 * needed even one that is two-dimensional; keeping them beside the state grammar
 * made a machine nobody could read in one pass.
 *
 * **Both send a ratio, never a coordinate** (the slider's rule): these functions
 * hold the elements, so they do the conversion, and every transition the machine
 * declares stays reachable from a node test. The area sends two ratios, one per
 * axis; a channel sends one.
 */

import { addDomEvent, isPrimaryPointer } from "../../dom/event";
import { getEventTarget, isHTMLElement } from "../../dom/query";
import { resolveDir } from "../../dom/text-dir";
import type { EffectCleanup, MachineParams } from "../../machine/types";
import type { Direction } from "../../types";
import type { ColorNumericChannel } from "../../utils/color";
import { getPercentFromPoint } from "../../utils/range";
import {
  CHANNEL_SLIDER_SELECTOR,
  getAreaEl,
  getChannelThumbEl,
  getSurfaceEl,
} from "./color-picker.dom";
import type { ColorPickerSchema } from "./color-picker.types";

type Params = MachineParams<ColorPickerSchema>;

/** How far the pointer has to travel before the click it leaves behind is eaten. */
const DRAG_THRESHOLD_PX = 4;

export function trackAreaPointer({ prop, scope, send }: Params): EffectCleanup {
  const area = getAreaEl(scope);
  if (area === null) return;

  let pointerId: number | null = null;
  let moved = false;
  let startX = 0;
  let startY = 0;
  // Resolved once per gesture: without a `dir` prop the answer comes from
  // `getComputedStyle`, which forces a style recalc, and a pointermove fires
  // once a frame while the writing direction never changes mid-drag.
  let dragDir: Direction = "ltr";

  // The thumb is centred on the value and overhangs the box at every edge,
  // so its own size takes nothing off the travel — `thumbSize: 0` on both
  // axes, which is `thumbAlignment: "center"` in the slider's vocabulary.
  const pointAt = (event: PointerEvent): { x: number; y: number } => {
    const rect = area.getBoundingClientRect();
    return {
      x: getPercentFromPoint(event.clientX, event.clientY, {
        rect,
        orientation: "horizontal",
        dir: dragDir,
        thumbSize: 0,
      }),
      y: getPercentFromPoint(event.clientX, event.clientY, {
        rect,
        orientation: "vertical",
        dir: dragDir,
        thumbSize: 0,
      }),
    };
  };

  const disposers = [
    addDomEvent(area, "pointerdown", (event: PointerEvent) => {
      if (pointerId !== null || !isPrimaryPointer(event)) return;
      if (prop("disabled") || prop("readOnly")) return;
      pointerId = event.pointerId;
      moved = false;
      startX = event.clientX;
      startY = event.clientY;
      dragDir = resolveDir(prop("dir"), area);
      const point = pointAt(event);
      try {
        area.setPointerCapture(event.pointerId);
      } catch {
        // A pointer that is already gone still deserves the rest of the
        // sequence; capture is an optimisation, not a precondition.
      }
      // No text selection, no native image drag, no focus stolen by the
      // browser — `focusAreaInput` places it deliberately instead.
      event.preventDefault();
      send({ type: "AREA.PRESS", x: point.x, y: point.y });
    }),

    addDomEvent(area, "pointermove", (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return;
      if (
        Math.abs(event.clientX - startX) >= DRAG_THRESHOLD_PX ||
        Math.abs(event.clientY - startY) >= DRAG_THRESHOLD_PX
      ) {
        moved = true;
      }
      const point = pointAt(event);
      send({ type: "AREA.DRAG", x: point.x, y: point.y });
    }),

    addDomEvent(area, "pointerup", (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return;
      pointerId = null;
      // Browsers do not guarantee a final pointermove at the release point.
      const point = pointAt(event);
      send({ type: "AREA.DRAG", x: point.x, y: point.y });
      send({ type: "AREA.DRAG_END", moved });
    }),

    addDomEvent(area, "pointercancel", (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return;
      pointerId = null;
      send({ type: "AREA.DRAG_END", moved });
    }),

    // A drag that ends inside the area still produces a click. Swallowing it
    // is what keeps a consumer's own handler from acting on a gesture that
    // was never a click (precedent: switch, slider).
    addDomEvent(
      area,
      "click",
      (event: MouseEvent) => {
        if (!moved) return;
        event.preventDefault();
        event.stopPropagation();
      },
      { capture: true },
    ),
  ];

  return () => {
    if (pointerId !== null) {
      try {
        area.releasePointerCapture(pointerId);
      } catch {
        // Already released by the browser — nothing left to hand back.
      }
    }
    for (const dispose of disposers.reverse()) dispose();
  };
}

/**
 * One set of listeners for every channel, delegated on the surface: a
 * picker draws up to four tracks and installing four gesture handlers would
 * be four times the teardown for one pointer that can only be on one of them.
 */
export function trackChannelPointer({ prop, scope, send }: Params): EffectCleanup {
  const surface = getSurfaceEl(scope);
  if (surface === null) return;

  let pointerId: number | null = null;
  let slider: HTMLElement | null = null;
  // The track the last gesture was on, kept past `release` because the click
  // arrives after it — it is what bounds the swallower at the bottom of the list
  // to the one element the area's swallower is bound to by construction.
  let dragged: HTMLElement | null = null;
  let thumbSize = 0;
  let moved = false;
  let startX = 0;
  let dragDir: Direction = "ltr";

  const release = (): void => {
    if (pointerId !== null && slider !== null) {
      try {
        slider.releasePointerCapture(pointerId);
      } catch {
        // Already released by the browser — nothing left to hand back.
      }
    }
    pointerId = null;
    slider = null;
  };

  const percentAt = (event: PointerEvent): number => {
    if (slider === null) return 0;
    return getPercentFromPoint(event.clientX, event.clientY, {
      rect: slider.getBoundingClientRect(),
      orientation: "horizontal",
      dir: dragDir,
      thumbSize,
    });
  };

  const disposers = [
    addDomEvent(surface, "pointerdown", (event: PointerEvent) => {
      if (pointerId !== null || !isPrimaryPointer(event)) return;
      // Spent here, before the guards, and not where the gesture starts: the click
      // swallower at the bottom of this list is bound to the *whole surface*, so a
      // flag left standing by the last drag ate the first click on a swatch, on
      // Close or on the eyedropper (audit of 2026-09-05). A fresh primary
      // pointerdown is a new interaction whatever it lands on.
      moved = false;
      if (prop("disabled") || prop("readOnly")) return;
      const target = getEventTarget(event);
      if (!isHTMLElement(target)) return;
      const found = target.closest<HTMLElement>(CHANNEL_SLIDER_SELECTOR);
      const channel = (found?.getAttribute("data-channel") ?? null) as ColorNumericChannel | null;
      if (found === null || channel === null) return;

      pointerId = event.pointerId;
      slider = found;
      dragged = found;
      startX = event.clientX;
      dragDir = resolveDir(prop("dir"), found);
      // Measured once per gesture: the knob's centre travels a track
      // shortened by one knob, and the element is the only place that width
      // exists — the CSS owns it.
      thumbSize = getChannelThumbEl(scope, channel)?.getBoundingClientRect().width ?? 0;

      try {
        found.setPointerCapture(event.pointerId);
      } catch {
        // See the area's handler: capture is an optimisation.
      }
      event.preventDefault();
      send({ type: "CHANNEL.PRESS", channel, percent: percentAt(event) });
    }),

    addDomEvent(surface, "pointermove", (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return;
      if (Math.abs(event.clientX - startX) >= DRAG_THRESHOLD_PX) moved = true;
      send({ type: "CHANNEL.DRAG", percent: percentAt(event) });
    }),

    addDomEvent(surface, "pointerup", (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return;
      // Browsers do not guarantee a final pointermove at the release point.
      send({ type: "CHANNEL.DRAG", percent: percentAt(event) });
      release();
      send({ type: "CHANNEL.DRAG_END", moved });
    }),

    addDomEvent(surface, "pointercancel", (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return;
      release();
      send({ type: "CHANNEL.DRAG_END", moved });
    }),

    // A drag that ends on the track still produces a click, and swallowing it is
    // what keeps a consumer's handler from acting on a gesture that was never a
    // click. Bound to the surface because the tracks are delegated (see above), so
    // it has to ask the question the area's handler gets for free: *this* track,
    // and not the swatch or the Close button the reader clicked next.
    addDomEvent(
      surface,
      "click",
      (event: MouseEvent) => {
        if (!moved || dragged === null) return;
        const target = getEventTarget(event);
        if (!isHTMLElement(target)) return;
        if (target.closest<HTMLElement>(CHANNEL_SLIDER_SELECTOR) !== dragged) return;
        event.preventDefault();
        event.stopPropagation();
      },
      { capture: true },
    ),
  ];

  return () => {
    release();
    for (const dispose of disposers.reverse()) dispose();
  };
}

/**
 * What this component adds on top of the shared arithmetic: turning an input —
 * eight keys, a modifier, or a d-pad — into one of the value events.
 *
 * **`Home`/`End` and the vertical axis never mirror.** RTL flips left and right
 * and nothing else: the APG says Home is *the minimum value*, not the left end,
 * and up/down have no writing order to follow. The mirror therefore lives in
 * exactly one function, `resolveDirection`, the way it does on the slider.
 *
 * Written here rather than imported from `slider.props`, and the reason is
 * measurable rather than stylistic: a `../slider/slider.props.js` import is not
 * covered by the `../../*` external of the budget script, so it would be counted
 * twice — once on this component's line and once on the slider's. It diverges on
 * two points anyway. **Shift+arrow is consumed here** (the slider leaves it to the
 * text selection it might be taking away; an area and a colour track have no text
 * in them, and Shift is the step modifier every colour picker on the market
 * uses), and the area needs a two-axis intent the slider has never had.
 *
 * The swatch grid is not here at all: `collection/grid-collection` gained a
 * `dir` option, so `getGridKeyAction(key, { dir, ctrlKey })` already answers the
 * §6.6 table — reading right-to-left mirrored, `Home`/`End` bounded to the row and
 * `Ctrl+Home`/`Ctrl+End` to the grid. Restating it as a `getSwatchKeyAction`
 * would be a second copy of a mirror that is now shared.
 */

import type { EngageIntent } from "../../nav";
import type { Direction } from "../../types";
import type { ColorNumericChannel } from "../../utils/color";
import type {
  ColorPickerAreaAdjustEvent,
  ColorPickerAreaAxis,
  ColorPickerChannelAdjustEvent,
} from "./color-picker.types";

export type ColorAdjustmentKind = "increment" | "decrement" | "min" | "max";

export interface ColorAdjustment {
  readonly kind: ColorAdjustmentKind;
  readonly large: boolean;
}

/** The eight APG keys, mapped onto the same intents a pad produces. */
const KEY_INTENTS: Readonly<Record<string, EngageIntent>> = {
  ArrowRight: "moveRight",
  ArrowLeft: "moveLeft",
  ArrowUp: "moveUp",
  ArrowDown: "moveDown",
  PageUp: "pageUp",
  PageDown: "pageDown",
  Home: "home",
  End: "end",
};

export function getKeyIntent(key: string): EngageIntent | null {
  return KEY_INTENTS[key] ?? null;
}

/** The mirror, in one place. Only `moveLeft`/`moveRight` ever reach the RTL branch. */
export function resolveDirection(intent: EngageIntent, dir: Direction): ColorAdjustment {
  const mirrored = dir === "rtl";
  switch (intent) {
    case "moveRight":
      return { kind: mirrored ? "decrement" : "increment", large: false };
    case "moveLeft":
      return { kind: mirrored ? "increment" : "decrement", large: false };
    case "moveUp":
      return { kind: "increment", large: false };
    case "moveDown":
      return { kind: "decrement", large: false };
    case "pageUp":
      return { kind: "increment", large: true };
    case "pageDown":
      return { kind: "decrement", large: true };
    case "home":
      return { kind: "min", large: false };
    default:
      return { kind: "max", large: false };
  }
}

/** Written once so the keyboard and the engage scope cannot send different events. */
export function toChannelAdjustEvent(
  adjustment: ColorAdjustment,
  channel: ColorNumericChannel,
): ColorPickerChannelAdjustEvent {
  const { kind, large } = adjustment;
  if (kind === "increment") return { type: "CHANNEL.INCREMENT", channel, large };
  if (kind === "decrement") return { type: "CHANNEL.DECREMENT", channel, large };
  if (kind === "min") return { type: "CHANNEL.SET_MIN", channel };
  return { type: "CHANNEL.SET_MAX", channel };
}

export function toAreaAdjustEvent(
  adjustment: ColorAdjustment,
  axis: ColorPickerAreaAxis,
): ColorPickerAreaAdjustEvent {
  const { kind, large } = adjustment;
  if (kind === "min") return { type: "AREA.SET_EXTREME", axis, edge: "min" };
  if (kind === "max") return { type: "AREA.SET_EXTREME", axis, edge: "max" };
  return { type: "AREA.ADJUST", axis, direction: kind, large };
}

/**
 * Which axis an intent moves. Left and right are the saturation, up and down the
 * brightness — and the page keys go with the vertical pair, because a colour area
 * is read the way a chart is: the big move is up the light.
 */
export function getAreaAxis(intent: EngageIntent): ColorPickerAreaAxis {
  switch (intent) {
    case "moveLeft":
    case "moveRight":
    case "home":
    case "end":
      return "x";
    default:
      return "y";
  }
}

export interface ColorKeyOptions {
  readonly dir: Direction;
  readonly shiftKey: boolean;
}

/**
 * The area's keyboard, both axes on one element. `Shift` is the large step and
 * it also moves `Home`/`End` from the saturation onto the brightness — the only
 * way to reach the second axis's bounds from a single tab stop.
 */
export function getAreaKeyEvent(
  key: string,
  options: ColorKeyOptions,
): ColorPickerAreaAdjustEvent | null {
  const intent = getKeyIntent(key);
  if (intent === null) return null;
  const adjustment = resolveDirection(intent, options.dir);
  const bound = adjustment.kind === "min" || adjustment.kind === "max";
  const axis: ColorPickerAreaAxis = bound && options.shiftKey ? "y" : getAreaAxis(intent);
  return toAreaAdjustEvent(
    { kind: adjustment.kind, large: adjustment.large || (options.shiftKey && !bound) },
    axis,
  );
}

/** A channel track's keyboard. One axis, so the mirror is the whole of RTL here. */
export function getChannelKeyEvent(
  key: string,
  channel: ColorNumericChannel,
  options: ColorKeyOptions,
): ColorPickerChannelAdjustEvent | null {
  const intent = getKeyIntent(key);
  if (intent === null) return null;
  const adjustment = resolveDirection(intent, options.dir);
  const bound = adjustment.kind === "min" || adjustment.kind === "max";
  return toChannelAdjustEvent(
    { kind: adjustment.kind, large: adjustment.large || (options.shiftKey && !bound) },
    channel,
  );
}

/**
 * The overlay half of the machine's effects, in a module of its own.
 *
 * Not a second component and not a barrel — the folder's own `index.ts` is still
 * the only one. This is the split the size of the machine asked for: the picker
 * carries an overlay, a collection, a two-dimensional control and up to four
 * one-dimensional ones, and the surface's six effects are the one group that has
 * nothing to do with the colour. They are the same effects the machine installs;
 * they are simply written where they can be read.
 *
 * Every one of them is inert in `presentation="inline"`: there is no layer to
 * dismiss, nothing to anchor, no focus to trap and no page to lock.
 */

import { hideOthers } from "../../a11y/aria-hidden";
import { lockScroll } from "../../a11y/scroll-lock";
import { resolveDir } from "../../dom/text-dir";
import { trapFocus } from "../../focus/focus-trap";
import { proxyTabFocus } from "../../focus/proxy-tab-focus";
import { focusWentElsewhere, restoreFocus } from "../../focus/restore-focus";
import { trackDismissableLayer } from "../../interaction/dismissable";
import { getLayerStack } from "../../interaction/layer-stack";
import type { EffectCleanup, MachineParams } from "../../machine/types";
import { focusElement, getFirstTabbable } from "../../nav";
import { trackPosition } from "../../positioner/track-position";
import type { ColorChannel } from "../../utils/color";
import {
  getBackdropId,
  getCancelTriggerId,
  getContentEl,
  getContentId,
  getFormatSelectEl,
  getPositionerEl,
  getRootEl,
  getTriggerEl,
} from "./color-picker.dom";
import type { ColorPickerSchema } from "./color-picker.types";

type Params = MachineParams<ColorPickerSchema>;

/** The inline properties `trackPosition` writes and never cleans up itself. */
const POSITION_STYLES = ["position", "top", "left", "transform", "width"] as const;

/**
 * The surface is portalled into the body, outside whatever RTL region the trigger
 * sits in, and inheritance does not cross a portal — so the direction is read from
 * the anchor and carried over explicitly. In an effect, so the server emits
 * nothing and the first client render has nothing to disagree with.
 */
export function trackSurfaceDir({ prop, context, computed, scope }: Params): EffectCleanup {
  if (computed("presentation") === "inline") return;
  context.set("surfaceDir", resolveDir(prop("dir"), getTriggerEl(scope) ?? getRootEl(scope)));
}

export function trackDismissable({ prop, context, computed, scope, send }: Params): EffectCleanup {
  if (computed("presentation") === "inline") return;
  return trackDismissableLayer(getContentEl(scope), {
    /**
     * The first Escape inside a channel field reverts what was typed; the second
     * one closes the surface. The veto has to live here and not on the field: the
     * layer listens on the *document in capture*, so a `stopPropagation` from the
     * target could never get there first.
     */
    onEscapeKeyDown(event) {
      const active = scope.getActiveElement();
      const part = active?.getAttribute("data-part") ?? "";
      if (!part.split(" ").includes("color-picker:channel-input")) return;
      const channel = active?.getAttribute("data-channel") ?? null;
      if (channel === null || context.get("inputDrafts")[channel] === undefined) return;
      event.preventDefault();
      send({ type: "INPUT.REVERT", channel: channel as ColorChannel });
    },
    id: getContentId(scope),
    type: "dialog",
    modal: computed("isModal"),
    parentId: prop("parentId"),
    // The format select is the one native control in the anatomy and its dropdown
    // is painted by the system, outside the DOM: on some engines a click inside it
    // arrives as an interaction *outside* the surface. The sheet's cancel may sit
    // beside the content, as the date picker's does: a press on it was outside and
    // closed with `outside-pointer`, keeping the colour it exists to put back (R73).
    exclude: () => [
      getTriggerEl(scope),
      getFormatSelectEl(scope),
      scope.getById(getCancelTriggerId(scope)),
      ...(prop("persistentElements")?.() ?? []),
    ],
    onDismiss: (reason) => send({ type: "CONTENT.DISMISS", reason }),
  });
}

export function lockPageScroll({ computed, scope }: Params): EffectCleanup {
  if (!computed("isModal")) return;
  return lockScroll(getContentEl(scope)?.ownerDocument);
}

/**
 * The sheet branch clears what a previous popup pass left behind, on install
 * rather than on teardown: a disposer would run while `presence` still holds the
 * node for its exit, and the surface would snap to `0,0` mid-fade.
 */
export function trackAnchorPosition({ prop, computed, scope, send }: Params): EffectCleanup {
  const positioner = getPositionerEl(scope);
  if (positioner === null) return;

  if (computed("presentation") !== "popup") {
    for (const name of POSITION_STYLES) positioner.style.removeProperty(name);
    positioner.style.removeProperty("--sui-transform-origin");
    return;
  }

  return trackPosition(getTriggerEl(scope), positioner, {
    placement: prop("placement"),
    gap: prop("gap"),
    offset: prop("offset"),
    flip: prop("flip"),
    shift: prop("shift"),
    padding: prop("padding"),
    dir: resolveDir(prop("dir"), getTriggerEl(scope)),
    strategy: prop("strategy"),
    boundary: prop("boundary"),
    onPositioned: (result) => send({ type: "POSITION.SYNC", placement: result.placement }),
  });
}

/**
 * Modal surfaces trap; anchored ones place the focus, send Tab on past the
 * trigger as a popover does, and hand the focus back. The trap is never installed
 * on a popup, for the popover's reason: a trapped scope silences the spatial
 * engine and makes the surface's own interior unreachable to a d-pad.
 */
export function trackFocusTrap({ prop, computed, refs, scope }: Params): EffectCleanup {
  if (computed("presentation") === "inline") return;
  const content = getContentEl(scope);
  if (content === null) return;
  const finalFocus = (): HTMLElement | null =>
    prop("finalFocus")?.() ?? refs.get("finalFocusEl") ?? getTriggerEl(scope);

  if (computed("isModal")) {
    // Spec §5.5 promises two rules for the format select in a modal surface.
    // Rule 1 — excluded from outside-pointer dismiss — lives in `trackDismissable`
    // above. Rule 2 is missing: `trapFocus` should not redirect a `focusout`
    // whose `relatedTarget` is `null` while the format select is the
    // `activeElement`, the signature of its own OS-drawn dropdown rather than a
    // focus leak, and neither `trapFocus` nor this call site knows that
    // exemption. Left open because mainstream engines keep `activeElement`
    // pinned on a `<select>` for the whole life of its dropdown — nothing in the
    // support matrix has been seen to hit the gap — and proving a fix would mean
    // adding an exemption option to `focus-trap.ts`, shared by every modal
    // surface in the library, carried entirely by a synthetic `focusout` standing
    // in for a browser behaviour no real engine here produces. That is the cost:
    // a shared-file change plus a synthetic-event test, for a guarantee no engine
    // currently forces.
    return trapFocus(content, { finalFocus, restoreFocus: prop("restoreFocus") });
  }

  // The positioner, not the content: the sheet's cancel may sit beside the
  // content, and a press on it leaves the focus there (R73).
  const layer = getPositionerEl(scope) ?? content;
  focusElement(getFirstTabbable(content) ?? content);
  const disposeTabs = proxyTabFocus(content, { triggerNode: () => getTriggerEl(scope) });
  return () => {
    disposeTabs();
    if (!prop("restoreFocus")) return;
    if (focusWentElsewhere(scope.getDoc(), layer, scope.getActiveElement())) return;
    const target = finalFocus();
    restoreFocus(target, layer);
  };
}

export function hideOutside({ prop, computed, scope }: Params): EffectCleanup {
  if (!computed("isModal")) return;
  return hideOthers(
    [
      getContentEl(scope),
      getPositionerEl(scope),
      scope.getById(getBackdropId(scope)),
      ...(prop("persistentElements")?.() ?? []),
    ],
    { inert: true },
  );
}

/**
 * B closes the surface — but only while nothing is held: the engage scope is
 * pushed above this one and consumes `back` first, which is what lets a gamepad
 * back out of a channel without losing the panel. A keyboard `back` is left to
 * the dismissable layer, whose Escape veto reverts a typed draft first.
 */
export function captureSurfaceIntents({ prop, computed, scope, send }: Params): EffectCleanup {
  if (computed("presentation") === "inline") return;
  const host = prop("intents");
  const content = getContentEl(scope);
  if (host === null || content === null) return;
  const id = getContentId(scope);
  const stack = getLayerStack(content.ownerDocument);

  return host.pushScope((event) => {
    if (event.intent !== "back" || event.source === "keyboard") return false;
    if (!prop("closeOnEscape") || !stack.isTopMost(id)) return false;
    send({ type: "CONTENT.DISMISS", reason: "back" });
    return true;
  });
}

import type { DismissReason } from "../../interaction/layer-stack";
import type { PropTypes } from "../../machine/prop-types";
import type { EffectCleanup, MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Placement } from "../../positioner/compute-position";
import type { Density, Direction, InputModality, Rect } from "../../types";
import type {
  ColorChannel,
  ColorFormat,
  ColorNumericChannel,
  ColorValue,
  RgbColor,
} from "../../utils/color";

/** What the surface actually is once the density has had its say. */
export type ColorPickerPresentation = "popup" | "sheet" | "inline";

export type ColorPickerPresentationProp = "auto" | ColorPickerPresentation;

/** The well is the capsule; the wheel is its round twin. */
export type ColorPickerVariant = "well" | "wheel";

/** What a gamepad can take hold of: any channel, or the area's two axes at once. */
export type ColorPickerEngageTarget = ColorNumericChannel | "area";

export type ColorPickerAreaAxis = "x" | "y";

export interface ColorPickerValueChangeDetails {
  /**
   * The colour formatted in the current format. The one exception is the end of a
   * gesture (`onValueChangeEnd`) under a controlled parent: when the reported
   * colour is the one the parent holds and that string parses, `value` is the
   * parent's own string, unchanged, whatever its notation. The hidden input still
   * submits the formatted colour.
   */
  readonly value: string;
  readonly color: ColorValue;
}

export interface ColorPickerOpenChangeDetails {
  readonly open: boolean;
}

export interface ColorPickerFormatChangeDetails {
  readonly format: ColorFormat;
}

export interface ColorPickerDismissDetails {
  readonly reason: DismissReason;
}

/**
 * The accessible names the panel owes when the consumer renders no label part of
 * its own, behind one named seam — the shape `toast` and `pagination` already use
 * (`ToastTranslations`, `PaginationTranslations`).
 *
 * The defaults stay English and stay in `connect`: five components in this library
 * ship an English default this way, and the alternative is a nameless icon-only
 * button. What was wrong until 2026-09-06 was not the English, it was that the
 * strings were written at the getter with no seam at all — the one component in
 * the repo in that position. `calendar` and `date-field` need no equivalent
 * because `Intl` has a table for weekday and field names; there is none for
 * "Add current color".
 *
 * `areaValueText` is the one that matters most and the one no part prop could
 * reach: it is composed inside the getter, and it is the sentence a screen reader
 * actually speaks on every drag of the area.
 */
export interface ColorPickerTranslations {
  /** Defaults to `"Close"`. */
  readonly closeLabel?: string | undefined;
  /** Defaults to `"Saturation and brightness"`. */
  readonly areaLabel?: string | undefined;
  /** Defaults to `"Color format"`. */
  readonly formatSelectLabel?: string | undefined;
  /** Defaults to `"Color swatches"`. */
  readonly swatchGroupLabel?: string | undefined;
  /** Defaults to `"Add current color"`. */
  readonly swatchTriggerLabel?: string | undefined;
  /** Defaults to `"Pick a color from the screen"`. */
  readonly eyedropperLabel?: string | undefined;
  /**
   * The name of one channel, used both for a slider with no `channelLabel` part
   * and for the two visually hidden range inputs of the area. Defaults to `"Hue"`,
   * `"Saturation"`, `"Brightness"`, `"Opacity"`, `"Red"`, `"Green"`, `"Blue"`,
   * `"Hex"`.
   */
  readonly channelLabel?: ((channel: ColorChannel) => string) | undefined;
  /**
   * What the area announces. Defaults to `"Saturation 40%, brightness 90%, <name>"`,
   * led by whichever axis the reader is on.
   */
  readonly areaValueText?:
    | ((details: {
        readonly lead: "saturation" | "brightness";
        readonly saturation: number;
        readonly brightness: number;
        readonly colorName: string;
      }) => string)
    | undefined;
}

/**
 * The screen picker, imported from `@standarui/core/color-picker/eyedropper` and
 * passed as is. Opaque on purpose: the module's own functions take the machine's
 * params, and method signatures are bivariant in their parameters, so they stay
 * assignable without this public type naming the machine's schema. The disposer
 * `detect` returns runs when the prop changes and when the picker goes away.
 */
export interface ColorPickerEyedropper {
  detect(params: object): EffectCleanup;
  open(params: object): void;
}

export interface ColorPickerMachineProps {
  // --- value -----------------------------------------------------------------
  /** A CSS colour string. Controlled when present — the machine reports, never writes. */
  readonly value?: string | undefined;
  readonly defaultValue?: string | undefined;
  readonly onValueChange?: ((details: ColorPickerValueChangeDetails) => void) | undefined;
  /** Once per gesture, with the colour the gesture aimed at — whether or not a controlled parent has answered yet; a gesture that writes nothing, or whose write lands back on the colour held (a drag brought back, B, Cancel), reports that colour — as the parent's own string when it holds it and that string parses. */
  readonly onValueChangeEnd?: ((details: ColorPickerValueChangeDetails) => void) | undefined;
  readonly format?: ColorFormat | undefined;
  readonly defaultFormat?: ColorFormat | undefined;
  readonly onFormatChange?: ((details: ColorPickerFormatChangeDetails) => void) | undefined;
  /** What the format select offers. Defaults to all four. */
  readonly formats?: readonly ColorFormat[] | undefined;
  /** `false` pins alpha at 1 and takes the alpha channel out of the anatomy. */
  readonly alpha?: boolean | undefined;

  // --- surface ---------------------------------------------------------------
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  readonly onOpenChange?: ((details: ColorPickerOpenChangeDetails) => void) | undefined;
  readonly presentation?: ColorPickerPresentationProp | undefined;
  readonly placement?: Placement | undefined;
  readonly gap?: number | undefined;
  readonly offset?: number | undefined;
  readonly flip?: boolean | undefined;
  readonly shift?: boolean | undefined;
  readonly padding?: number | undefined;
  readonly strategy?: "absolute" | "fixed" | undefined;
  readonly boundary?: (() => Rect) | undefined;
  /** Defaults to `false` in `popup` and `true` in `sheet`; ignored in `inline`. */
  readonly modal?: boolean | undefined;
  readonly closeOnEscape?: boolean | undefined;
  readonly closeOnInteractOutside?: boolean | undefined;
  readonly restoreFocus?: boolean | undefined;
  readonly finalFocus?: (() => HTMLElement | null) | undefined;
  readonly onDismiss?: ((details: ColorPickerDismissDetails) => void) | undefined;
  /** The layer this picker opened from — adapters default it from their context. */
  readonly parentId?: string | undefined;
  readonly persistentElements?: (() => readonly HTMLElement[]) | undefined;

  // --- control ---------------------------------------------------------------
  readonly disabled?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly required?: boolean | undefined;
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  readonly variant?: ColorPickerVariant | undefined;
  /** One arrow key, in the unit of whichever channel it lands on. */
  readonly step?: number | undefined;
  /**
   * Shift+arrow, PageUp/PageDown and the triggers. Absent, each channel takes a
   * tenth of its own range — 10 on saturation, 36 on hue, 0.1 on alpha — because
   * a flat ten would be a rounding error on a 0→360 channel.
   */
  readonly largeStep?: number | undefined;
  readonly swatches?: readonly string[] | undefined;
  readonly maxSwatches?: number | undefined;
  /** Defaults to 12 on desktop and 6 on touch — see the density table (§8). */
  readonly swatchColumns?: number | undefined;
  readonly loopSwatches?: boolean | undefined;
  /** The screen picker, imported from `@standarui/core/color-picker/eyedropper`; without it the part never renders, on any engine. */
  readonly eyedropper?: ColorPickerEyedropper | undefined;
  readonly labelledBy?: string | undefined;
  readonly describedBy?: string | undefined;
  /** The accessible name of the surface when no `title` part is rendered. */
  readonly label?: string | undefined;
  readonly translations?: ColorPickerTranslations | undefined;
  readonly intents?: IntentScopeHost | null | undefined;
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
}

export interface ResolvedColorPickerMachineProps extends ColorPickerMachineProps {
  readonly defaultValue: string;
  readonly defaultFormat: ColorFormat;
  readonly formats: readonly ColorFormat[];
  readonly alpha: boolean;
  readonly defaultOpen: boolean;
  readonly presentation: ColorPickerPresentationProp;
  readonly placement: Placement;
  readonly gap: number;
  readonly offset: number;
  readonly flip: boolean;
  readonly shift: boolean;
  readonly padding: number;
  readonly strategy: "absolute" | "fixed";
  readonly closeOnEscape: boolean;
  readonly closeOnInteractOutside: boolean;
  readonly restoreFocus: boolean;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly invalid: boolean;
  readonly required: boolean;
  readonly variant: ColorPickerVariant;
  readonly step: number;
  readonly swatches: readonly string[];
  readonly maxSwatches: number;
  readonly loopSwatches: boolean;
  readonly intents: IntentScopeHost | null;
}

/** The four value events an area axis produces, whatever pressed the key. */
export type ColorPickerAreaAdjustEvent =
  | {
      type: "AREA.ADJUST";
      axis: ColorPickerAreaAxis;
      direction: "increment" | "decrement";
      large: boolean;
    }
  | { type: "AREA.SET_EXTREME"; axis: ColorPickerAreaAxis; edge: "min" | "max" };

/** The four value events a channel produces, whatever pressed the key. */
export type ColorPickerChannelAdjustEvent =
  | { type: "CHANNEL.INCREMENT"; channel: ColorNumericChannel; large: boolean }
  | { type: "CHANNEL.DECREMENT"; channel: ColorNumericChannel; large: boolean }
  | { type: "CHANNEL.SET_MIN"; channel: ColorNumericChannel }
  | { type: "CHANNEL.SET_MAX"; channel: ColorNumericChannel };

export interface ColorPickerSchema extends MachineSchema {
  /**
   * **Two states, and `engaged` is deliberately not a third.** This interpreter
   * is flat: entering a state tears down the effects of the one it left
   * (`machine/service.ts`, `runTransition`). The slider can afford `engaged` as a
   * sibling because the state it leaves owns one effect; here `open` owns the
   * dismissable layer, the position tracker, the focus trap, the scroll lock and
   * the `aria-hidden` sweep — tearing those down to take hold of a knob would
   * close the layer, re-fit the surface and hand the focus back to the trigger.
   * The hold is `context.engagedTarget` plus a scope disposed by `trackEngage`,
   * which is the same guarantee with the effect where it can survive.
   */
  state: "closed" | "open";
  props: ResolvedColorPickerMachineProps;
  context: {
    /** HSVA, the source of truth. `colorEquals` keeps a fresh object from reading as a change. */
    color: ColorValue;
    open: boolean;
    format: ColorFormat;
    /** The channel a pointer or a pad is currently moving, `null` when none is. */
    activeChannel: ColorPickerEngageTarget | null;
    /** What the gamepad is holding, `null` when it holds nothing. */
    engagedTarget: ColorPickerEngageTarget | null;
    areaDragging: boolean;
    /** Roving index into the swatch grid; `-1` when nothing is highlighted. */
    highlightedSwatch: number;
    savedSwatches: string[];
    density: Density;
    surfaceDir: Direction | null;
    currentPlacement: Placement;
    /**
     * `false` until an effect has looked, so the server and the first client
     * render agree and the trigger appears after hydration rather than during it.
     */
    eyedropperSupported: boolean;
    /** The text a channel field holds before it is committed, keyed by channel. */
    inputDrafts: Record<string, string>;
    /** Channels whose last commit could not be parsed — `data-invalid` on the field alone. */
    invalidDrafts: string[];
    focusSource: InputModality | null;
    /**
     * Whether the parts an `aria-labelledby` would point at are rendered.
     * Read from the live DOM rather than assumed: an IDREF written blind is a
     * dangling reference *and* no accessible name at once, and `axe`'s
     * `aria-valid-attr-value` fails on it (the lesson `menu` and `field` both
     * carry).
     */
    hasLabel: boolean;
    hasTitle: boolean;
    /**
     * Whether `value-text` is on the page, which decides whether the trigger's
     * name can carry the colour. The trigger points its `aria-labelledby` at its
     * own id to mean "and my own contents" — but that is worth nothing when the
     * only child is the swatch, which is `aria-hidden`. Measured on the shipped
     * demo: the name came out "Accent", never the colour.
     */
    hasValueText: boolean;
    /** Which channels a `channel-label` was rendered for — see `getLabelledChannels`. */
    labelledChannels: string[];
  };
  computed: {
    presentation: ColorPickerPresentation;
    isInteractive: boolean;
    isModal: boolean;
    valueString: string;
    rgb: RgbColor;
    /** The channels that get a slider, in tab order. */
    channels: readonly ColorNumericChannel[];
    swatchList: readonly string[];
    swatchColumns: number;
    swatchRows: number;
    colorName: string;
  };
  refs: {
    /** The snapshot B restores to inside a hold — taken on every engage. */
    entryColor: ColorValue | null;
    /** The colour the surface opened with, which the sheet's cancel puts back. */
    openColor: ColorValue | null;
    /** The colour the last write aimed at, emitted or not, cleared when the end of a gesture reports it. */
    changed: ColorValue | null;
    finalFocusEl: HTMLElement | null;
    /** The live engage scope's dispose, so a release and an unmount share one path. */
    engageDispose: VoidFunction | null;
    /** Cancels a screen pick still in flight when the surface goes away. */
    eyedropperAbort: AbortController | null;
    /** The current module's disposer, one slot for the mount and for every change of the prop. */
    eyedropperEnd: VoidFunction | null;
    /** The photo `FORM.RESET` restores. */
    initialValue: string;
  };
  event:
    | ColorPickerAreaAdjustEvent
    | ColorPickerChannelAdjustEvent
    | { type: "TRIGGER.CLICK" }
    | { type: "CONTENT.DISMISS"; reason: DismissReason }
    | { type: "CANCEL.CLICK" }
    | { type: "CLOSE.CLICK" }
    | { type: "AREA.PRESS"; x: number; y: number }
    | { type: "AREA.DRAG"; x: number; y: number }
    | { type: "AREA.DRAG_END"; moved: boolean }
    /** The assistive-technology path: a real `<input type="range">` pushed a value. */
    | { type: "AREA.SET"; axis: ColorPickerAreaAxis; value: number }
    | { type: "CHANNEL.PRESS"; channel: ColorNumericChannel; percent: number }
    | { type: "CHANNEL.DRAG"; percent: number }
    | { type: "CHANNEL.DRAG_END"; moved: boolean }
    /** `api.setChannelValue` — in the channel's own unit, never the field's per cent. */
    | { type: "CHANNEL.SET"; channel: ColorNumericChannel; value: number }
    | { type: "CHANNEL.ENGAGE"; target: ColorPickerEngageTarget }
    | { type: "CHANNEL.RELEASE"; committed: boolean }
    /** The modality a value control's focus arrived under, held until it leaves. */
    | { type: "FOCUS.IN" }
    /** A Tab out of a held control ends the hold by committing (§6.0). */
    | { type: "FOCUS.OUT" }
    | { type: "INPUT.CHANGE"; channel: ColorChannel; text: string }
    | { type: "INPUT.COMMIT"; channel: ColorChannel }
    | { type: "INPUT.REVERT"; channel: ColorChannel }
    | { type: "FORMAT.SET"; format: ColorFormat }
    | { type: "SWATCH.SELECT"; index: number }
    | { type: "SWATCH.HIGHLIGHT"; index: number }
    | { type: "SWATCH.ADD" }
    | { type: "EYEDROPPER.OPEN" }
    | { type: "EYEDROPPER.RESULT"; sRGBHex: string }
    | { type: "EYEDROPPER.DISMISS"; reason: "abort" | "error" }
    | { type: "VALUE.SET"; value: string }
    | { type: "OPEN.SET"; open: boolean }
    | { type: "OPEN.SYNC" }
    | { type: "PRESENTATION.SYNC" }
    | { type: "POSITION.SYNC"; placement: Placement }
    | { type: "ENVIRONMENT.SYNC"; density: Density }
    | { type: "PARTS.SYNC" }
    | { type: "FORM.RESET" };
  action:
    | "openSurface"
    | "closeSurface"
    | "setOpen"
    | "captureFinalFocus"
    | "snapshotColor"
    | "snapshotOpenColor"
    | "restoreOpenColor"
    | "restoreEntryColor"
    | "clearSnapshot"
    | "startAreaDrag"
    | "endAreaDrag"
    | "setAreaFromPoint"
    | "setAreaAxis"
    | "adjustArea"
    | "setAreaExtreme"
    | "focusAreaInput"
    | "startChannelDrag"
    | "endChannelDrag"
    | "setChannelFromPercent"
    | "setChannelValue"
    | "adjustChannel"
    | "setChannelExtreme"
    | "focusChannelThumb"
    | "engageTarget"
    | "releaseTarget"
    | "captureFocusSource"
    | "clearFocusSource"
    | "setDraft"
    | "commitDraft"
    | "clearDraft"
    | "clearDrafts"
    | "setFormat"
    | "selectSwatch"
    | "highlightSwatch"
    | "saveCurrentSwatch"
    | "openEyedropper"
    | "applyEyedropper"
    | "clearEyedropper"
    | "setValueFromString"
    | "resetToInitialValue"
    | "invokeChangeEnd"
    | "invokeOnDismiss"
    | "syncEnvironment"
    | "syncPlacement"
    | "syncParts"
    | "syncEyedropper";
  guard:
    | "isInteractive"
    | "isOpen"
    | "isAreaDragging"
    | "isChannelDragging"
    | "isEngaged"
    | "canEngage"
    | "canDismiss"
    | "canEyedrop";
  effect:
    | "trackEnvironment"
    | "trackModality"
    | "trackParts"
    | "trackFormReset"
    | "detectEyedropper"
    | "trackSurfaceDir"
    | "trackDismissable"
    | "trackAnchorPosition"
    | "trackFocusTrap"
    | "hideOutside"
    | "lockPageScroll"
    | "captureSurfaceIntents"
    | "captureSelectIntent"
    | "trackEngage"
    | "trackAreaPointer"
    | "trackChannelPointer";
}

// --- prop-getter inputs ------------------------------------------------------

export interface ColorPickerChannelProps {
  readonly channel: ColorNumericChannel;
}

export interface ColorPickerInputProps {
  /** `"hex"` is the text field the hex format shows; everything else is numeric. */
  readonly channel: ColorChannel;
}

export interface ColorPickerSwatchRowProps {
  readonly row: number;
}

export interface ColorPickerSwatchProps {
  readonly index: number;
}

export interface ColorPickerApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  /** The colour formatted in the current format. */
  readonly value: string;
  readonly color: ColorValue;
  readonly rgb: RgbColor;
  readonly format: ColorFormat;
  readonly formats: readonly ColorFormat[];
  /** The channels that get a slider, in tab order. */
  readonly channels: readonly ColorNumericChannel[];
  readonly swatches: readonly string[];
  readonly swatchColumns: number;
  readonly swatchRows: number;
  readonly highlightedSwatch: number;
  readonly presentation: ColorPickerPresentation;
  readonly placement: Placement;
  readonly dragging: boolean;
  readonly engaged: boolean;
  readonly engagedTarget: ColorPickerEngageTarget | null;
  readonly disabled: boolean;
  /** `false` until an effect has looked — never read at render time (§5.2). */
  readonly eyedropperSupported: boolean;
  readonly focusSource: InputModality | null;
  readonly focusVisible: boolean;
  readonly triggerId: string;
  readonly contentId: string;

  setOpen(open: boolean): void;
  setValue(value: string): void;
  setColor(color: ColorValue): void;
  setFormat(format: ColorFormat): void;
